+      if (nativeSelect) {
+        nativeSelect.addEventListener('change', () => {
+          selectRoast(nativeSelect.value);
+        });
+      }
+
+      document.addEventListener('click', (e) => {
+        if (!roastSelector.contains(e.target)) {
+          closeDropdown();
+        }
+      });
+
+      document.addEventListener('keydown', (e) => {
+        if (e.key === 'Escape') {
+          closeDropdown();
+        }
+      });
+    })();
+  </script>
+
