+        link.download = `smallpt-${width}x${height}-${wasmInstance.exports.get_total_samples()}spp.png`;
+        link.href = canvas.toDataURL('image/png');
+        link.click();
+      });
+
+      // Instantiate WebAssembly (try fetch first, then base64 fallback)
+      async function initWasm() {
+        try {
+          let buffer;
+          try {
+            const resp = await fetch('smallpt.wasm');
+            if (resp.ok) {
+              buffer = await resp.arrayBuffer();
+            }
+          } catch (e) {
+            console.warn("fetch('smallpt.wasm') failed, trying embedded base64 fallback:", e);
+          }
+
+          if (!buffer && window.SMALLPT_WASM_BASE64) {
+            const binStr = atob(window.SMALLPT_WASM_BASE64);
+            const bytes = new Uint8Array(binStr.length);
+            for (let i = 0; i < binStr.length; i++) {
+              bytes[i] = binStr.charCodeAt(i);
+            }
+            buffer = bytes.buffer;
+          }
+
+          if (!buffer) {
+            throw new Error("Unable to obtain WebAssembly binary!");
+          }
+
+          const { instance } = await WebAssembly.instantiate(buffer, importObject);
+          wasmInstance = instance;
+
+          // Initialize Cornell Box Scene
+          wasmInstance.exports.init_scene();
+          updateSwatches();
+
+          // Hide loading overlay and start initial render
+          loadingOverlay.classList.add('hidden');
+          startRender();
+        } catch (err) {
+          console.error("Failed to load WebAssembly:", err);
+          statStatus.textContent = 'Error';
+          statStatus.style.color = '#ef4444';
+          loadingOverlay.innerHTML = `<div style="color: #ef4444; font-weight: 600; padding: 20px; text-align: center;">Error loading WebAssembly module:<br>${err.message}</div>`;
+        }
+      }
+
+      // Start initialization on page load
+      initWasm();
+    })();
+  </script>
+</body>
