+extern "C" {
+    double js_pow(double b, double e);
+}
+
+// Math functions mapped to WebAssembly intrinsics and efficient implementations
+static inline double my_sqrt(double x) {
+    return __builtin_sqrt(x);
+}
+
+static inline double my_fabs(double x) {
+    return __builtin_fabs(x);
+}
+
+static inline double my_sin(double x) {
+    const double PI = 3.14159265358979323846;
+    const double TWO_PI = 6.28318530717958647692;
+    while (x > PI) x -= TWO_PI;
+    while (x < -PI) x += TWO_PI;
+    double x2 = x * x;
+    return x * (1.0 + x2 * (-1.0/6.0 + x2 * (1.0/120.0 + x2 * (-1.0/5040.0 + x2 * (1.0/362880.0)))));
