+    (function () {
+      const themeToggleBtn = document.getElementById('theme-toggle');
+      const toggleIcon = themeToggleBtn ? themeToggleBtn.querySelector('.theme-toggle-icon') : null;
+      const toggleText = themeToggleBtn ? themeToggleBtn.querySelector('.theme-toggle-text') : null;
+
+      function getInitialTheme() {
+        try {
+          const savedTheme = localStorage.getItem('theme');
+          if (savedTheme === 'dark' || savedTheme === 'light') {
+            return savedTheme;
+          }
+        } catch (e) {}
+
+        if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
+          return 'dark';
+        }
+        return 'light';
+      }
+
+      function applyTheme(theme) {
+        const isDark = theme === 'dark';
+
+        document.documentElement.setAttribute('data-theme', theme);
+        document.body.setAttribute('data-theme', theme);
+
+        document.documentElement.classList.toggle('dark-mode', isDark);
+        document.documentElement.classList.toggle('dark-theme', isDark);
+        document.documentElement.classList.toggle('light-mode', !isDark);
+        document.documentElement.classList.toggle('light-theme', !isDark);
+
+        document.body.classList.toggle('dark-mode', isDark);
+        document.body.classList.toggle('dark-theme', isDark);
+        document.body.classList.toggle('light-mode', !isDark);
+        document.body.classList.toggle('light-theme', !isDark);
+
+        if (themeToggleBtn) {
+          themeToggleBtn.setAttribute('aria-pressed', isDark ? 'true' : 'false');
+          themeToggleBtn.setAttribute('aria-checked', isDark ? 'true' : 'false');
