+        <div class="audit-details-card">
+          <h4>Cryptographic Audit Report</h4>
+          <table class="audit-table">
+            <tbody>
+              <tr>
+                <td><strong>Verification Verdict</strong></td>
+                <td><span class="badge badge-success">VALID & UNTAMPERED</span></td>
+              </tr>
+              <tr>
+                <td><strong>Algorithm Suite</strong></td>
+                <td>
+                  <span class="badge ${isPq ? 'badge-pq' : 'badge-classical'}">
+                    ${isPq ? 'ML-DSA-65 (NIST FIPS 204 Post-Quantum Lattice)' : 'Ed25519 (RFC 8032 Classical Edwards-Curve)'}
+                  </span>
+                </td>
+              </tr>
+              <tr>
+                <td><strong>Domain Context</strong></td>
+                <td><code>${escapeHtml(contextToUse)}</code></td>
+              </tr>
+              <tr>
+                <td><strong>Signer Public Key Fingerprint</strong></td>
+                <td><code>${fingerprint}</code></td>
+              </tr>
+              <tr>
+                <td><strong>Key Length / Format</strong></td>
+                <td>${pubKeyBytes.byteLength} bytes (${isPq ? 'raw-public' : 'raw'})</td>
+              </tr>
+              <tr>
+                <td><strong>Signature Length</strong></td>
+                <td>${sigBytes.byteLength} bytes</td>
+              </tr>
+              <tr>
+                <td><strong>Canonical Payload SHA-256</strong></td>
+                <td><code>${payloadHashHex}</code></td>
+              </tr>
+              <tr>
+                <td><strong>Verification Execution Time</strong></td>
+                <td>${elapsedMs} ms</td>
+              </tr>
+            </tbody>
+          </table>
+        </div>
+      `;
+    } else {
+      let specificReason = 'Signature mismatch: The document payload has been modified or forged.';
+      if (contextMismatch) {
+        specificReason = `Domain Separation Mismatch: The signature was created for context <code>${escapeHtml(envelope.context)}</code> but verified with <code>${escapeHtml(contextToUse)}</code>. This protects against cross-protocol replay attacks (e.g., presenting a coffee receipt signature as a gift voucher).`;
+      }
+
+      resultContainer.innerHTML = `
+        <div class="result-alert alert-danger">
+          <div class="alert-icon">❌</div>
+          <div>
+            <h3>VERIFICATION FAILED / TAMPER DETECTED</h3>
+            <p>${specificReason}</p>
+          </div>
+        </div>
+
+        <div class="audit-details-card">
+          <h4>Cryptographic Audit Report</h4>
+          <table class="audit-table">
+            <tbody>
+              <tr>
+                <td><strong>Verification Verdict</strong></td>
+                <td><span class="badge badge-danger">INVALID / COMPROMISED</span></td>
+              </tr>
+              <tr>
+                <td><strong>Failure Cause</strong></td>
+                <td>${specificReason}</td>
+              </tr>
+              <tr>
+                <td><strong>Algorithm Suite</strong></td>
+                <td><code>${escapeHtml(algorithm || 'Auto-detected')}</code></td>
+              </tr>
+              <tr>
+                <td><strong>Evaluated Context</strong></td>
+                <td><code>${escapeHtml(contextToUse)}</code></td>
+              </tr>
+              <tr>
+                <td><strong>Signer Key Fingerprint</strong></td>
+                <td><code>${fingerprint}</code></td>
+              </tr>
+              <tr>
+                <td><strong>Canonical Payload SHA-256</strong></td>
+                <td><code>${payloadHashHex}</code></td>
+              </tr>
+              <tr>
+                <td><strong>Execution Time</strong></td>
+                <td>${elapsedMs} ms</td>
+              </tr>
+            </tbody>
+          </table>
+        </div>
+      `;
+    }
+  } catch (err) {
+    resultContainer.innerHTML = `
+      <div class="result-alert alert-danger">
+        <div class="alert-icon">⚠️</div>
+        <div>
+          <h3>Cryptographic Error During Verification</h3>
+          <p>${escapeHtml(err.message)}</p>
+        </div>
+      </div>
+    `;
+  }
+}
+
+// Preset samples loader for verification
+async function loadPortalPreset(presetType) {
+  if (!state.activeKeypair) {
+    await initCryptoAuthority(state.activeAlgorithm);
+  }
+
+  if (presetType === 'active-receipt') {
+    if (state.activeReceiptEnvelope) {
+      sendEnvelopeToPortal(state.activeReceiptEnvelope);
+    } else {
+      await issueCoffeeReceipt();
+      sendEnvelopeToPortal(state.activeReceiptEnvelope);
+    }
+  } else if (presetType === 'active-voucher') {
+    if (state.activeVoucherEnvelope) {
+      sendEnvelopeToPortal(state.activeVoucherEnvelope);
+    } else {
+      await issueGiftVoucher();
+      sendEnvelopeToPortal(state.activeVoucherEnvelope);
+    }
+  } else if (presetType === 'tampered-sample') {
+    // Generate fresh receipt, then tamper it
+    const now = new Date();
+    const samplePayload = {
+      orderId: 'ORD-SAMPLE-TAMPERED',
+      store: 'The Daily Grind - Roastery #01',
+      customer: 'Honest Customer',
+      timestamp: now.toISOString(),
+      items: [{ name: 'Maple Oat Latte', qty: 1, subtotal: 5.75 }],
+      financials: { total: 5.75 },
+    };
+    const can = canonicalJsonStringify(samplePayload);
+    const sig = await signPayload(state.activeKeypair.suite, state.activeKeypair.keyPair.privateKey, can, CONTEXTS.RECEIPT);
+    // Alter total after signing!
+    samplePayload.financials.total = 0.05;
+    const tamperedEnv = {
+      type: 'coffee-order-receipt',
+      context: CONTEXTS.RECEIPT,
+      algorithm: state.activeKeypair.suite,
+      signedAt: now.toISOString(),
+      publicKey: state.activeKeypair.publicKeyBase64,
+      signature: bytesToBase64(sig),
+      payload: samplePayload,
+    };
+    sendEnvelopeToPortal(tamperedEnv);
+    showToast('Loaded sample tampered document: total altered to $0.05!', 'warning');
+  } else if (presetType === 'replay-attack') {
+    // Cross-context replay: voucher signed with CONTEXTS.VOUCHER, but passed as CONTEXTS.RECEIPT
+    const now = new Date();
+    const samplePayload = {
+      orderId: 'ORD-REPLAY-ATTACK',
+      customer: 'Attacker Replay',
+      total: 50.00,
+    };
+    const can = canonicalJsonStringify(samplePayload);
+    // Sign with VOUCHER context
+    const sig = await signPayload(state.activeKeypair.suite, state.activeKeypair.keyPair.privateKey, can, CONTEXTS.VOUCHER);
+    // Present as receipt
+    const replayEnv = {
+      type: 'coffee-order-receipt',
+      context: CONTEXTS.RECEIPT, // context mismatch with signature!
+      algorithm: state.activeKeypair.suite,
+      publicKey: state.activeKeypair.publicKeyBase64,
+      signature: bytesToBase64(sig),
+      payload: samplePayload,
+    };
+    sendEnvelopeToPortal(replayEnv);
+    showToast('Loaded cross-context replay attack sample!', 'warning');
+  }
+}
+
+// Utility: HTML Escaping
+function escapeHtml(str) {
+  if (typeof str !== 'string') return String(str ?? '');
+  return str.replace(/[&<>"']/g, match => {
+    switch (match) {
+      case '&': return '&amp;';
+      case '<': return '&lt;';
+      case '>': return '&gt;';
+      case '"': return '&quot;';
+      case "'": return '&#39;';
+      default: return match;
+    }
+  });
+}
+
+// Event Bindings and Setup
+function setupEventListeners() {
+  // Authority Algorithm Change
+  document.getElementById('authority-algorithm-select')?.addEventListener('change', async (e) => {
+    const selectedAlgo = e.target.value;
+    await initCryptoAuthority(selectedAlgo);
+    showToast(`Switched active cryptographic suite to ${selectedAlgo}`, 'info');
+  });
+
+  // Regenerate Keys
+  document.getElementById('authority-regenerate-btn')?.addEventListener('click', async () => {
+    const algo = document.getElementById('authority-algorithm-select')?.value || 'ML-DSA-65';
+    await initCryptoAuthority(algo);
+    showToast('Generated new store authority keypair!', 'success');
+  });
+
+  // Copy Public Key
+  document.getElementById('authority-copy-key-btn')?.addEventListener('click', () => {
+    if (state.activeKeypair) {
+      copyToClipboard(state.activeKeypair.publicKeyBase64, 'Store public key copied to clipboard!');
+    }
+  });
+
+  // Order Form Inputs Change -> Recalculate Totals
+  const orderInputs = ['order-coffee', 'order-size', 'order-milk', 'order-qty', 'order-extra-shot', 'order-extra-vanilla', 'order-extra-cinnamon'];
+  orderInputs.forEach(id => {
+    document.getElementById(id)?.addEventListener('change', calculateOrderTotals);
+    document.getElementById(id)?.addEventListener('input', calculateOrderTotals);
+  });
+
+  // Place Order Button
+  document.getElementById('order-submit-btn')?.addEventListener('click', async (e) => {
+    e.preventDefault();
+    await issueCoffeeReceipt();
+  });
+
+  // Voucher Amount Quick Select Buttons
+  document.querySelectorAll('.amount-preset-btn').forEach(btn => {
+    btn.addEventListener('click', () => {
+      document.querySelectorAll('.amount-preset-btn').forEach(b => b.classList.remove('active'));
+      btn.classList.add('active');
+      const amtInput = document.getElementById('voucher-amount');
+      if (amtInput) amtInput.value = btn.dataset.amount;
+    });
+  });
+
+  // Issue Voucher Button
+  document.getElementById('voucher-submit-btn')?.addEventListener('click', async (e) => {
+    e.preventDefault();
+    await issueGiftVoucher();
+  });
+
+  // Verification Portal Action
+  document.getElementById('verify-run-btn')?.addEventListener('click', async () => {
+    await runPortalVerification();
+  });
+
+  // Portal Preset Loaders
+  document.getElementById('portal-load-receipt')?.addEventListener('click', () => loadPortalPreset('active-receipt'));
+  document.getElementById('portal-load-voucher')?.addEventListener('click', () => loadPortalPreset('active-voucher'));
+  document.getElementById('portal-load-tampered')?.addEventListener('click', () => loadPortalPreset('tampered-sample'));
+  document.getElementById('portal-load-replay')?.addEventListener('click', () => loadPortalPreset('replay-attack'));
+
+  // Quick Action from Seasonal Cards to Order Form
+  document.querySelectorAll('.order-card-btn').forEach(btn => {
+    btn.addEventListener('click', (e) => {
+      e.preventDefault();
+      const coffeeId = btn.dataset.coffee;
+      const coffeeSelect = document.getElementById('order-coffee');
+      if (coffeeSelect && coffeeId) {
+        coffeeSelect.value = coffeeId;
+        calculateOrderTotals();
+      }
+      document.getElementById('order-section')?.scrollIntoView({ behavior: 'smooth' });
+    });
+  });
+}
+
+// Bootstrap Application
+export async function initApp() {
+  // Detect algorithms
+  const isPq = supportsPostQuantumSignatures();
+  const defaultAlgo = isPq ? 'ML-DSA-65' : 'Ed25519';
+
+  await initCryptoAuthority(defaultAlgo);
+  calculateOrderTotals();
+  setupEventListeners();
+
+  // Generate initial signed receipt and voucher on load for immediate showcase
+  await issueCoffeeReceipt();
+  await issueGiftVoucher();
+}
+
+if (typeof document !== 'undefined') {
+  document.addEventListener('DOMContentLoaded', initApp);
+}
