+    const bytes = typeof data === 'string' ? new TextEncoder().encode(data) : data;
+    return new Uint8Array(await subtle.digest('SHA-256', bytes));
+  }
+
+  // --- Classical Asymmetric Cryptography (ECDSA P-256 & RSA-PSS) ---
+
+  const CLASSICAL_ALGORITHMS = {
+    'ECDSA-P256': {
+      name: 'ECDSA-P256-SHA256',
+      type: 'classical',
+      displayName: 'Classical ECDSA (NIST P-256 + SHA-256)',
+      keygenParams: { name: 'ECDSA', namedCurve: 'P-256' },
+      signParams: { name: 'ECDSA', hash: { name: 'SHA-256' } },
+      importParams: { name: 'ECDSA', namedCurve: 'P-256' }
+    },
+    'RSA-PSS-2048': {
+      name: 'RSA-PSS-2048-SHA256',
+      type: 'classical',
+      displayName: 'Classical RSA-PSS (2048-bit + SHA-256)',
+      keygenParams: {
+        name: 'RSA-PSS',
+        modulusLength: 2048,
+        publicExponent: new Uint8Array([1, 0, 1]),
+        hash: 'SHA-256'
+      },
+      signParams: { name: 'RSA-PSS', saltLength: 32 },
+      importParams: { name: 'RSA-PSS', hash: 'SHA-256' }
+    }
+  };
+
+  async function generateClassicalKeyPair(algoKey = 'ECDSA-P256') {
+    const config = CLASSICAL_ALGORITHMS[algoKey] || CLASSICAL_ALGORITHMS['ECDSA-P256'];
+    const keyPair = await subtle.generateKey(config.keygenParams, true, ['sign', 'verify']);
+    const publicJwk = await subtle.exportKey('jwk', keyPair.publicKey);
+    const privateJwk = await subtle.exportKey('jwk', keyPair.privateKey);
+
+    const pubBytes = new TextEncoder().encode(JSON.stringify(publicJwk));
+    const fpBytes = await sha256(pubBytes);
+    const fingerprint = bytesToHex(fpBytes).substring(0, 16).toUpperCase();
+
+    return {
+      algorithm: config.name,
+      keyType: 'classical',
+      keyId: 'DG-' + config.name.split('-')[0] + '-' + fingerprint.substring(0, 8),
+      fingerprint,
+      publicKey: keyPair.publicKey,
+      privateKey: keyPair.privateKey,
+      publicJwk,
+      privateJwk
