+  }
+
+  async function signClassical(payloadString, privateKey, algoName) {
+    const data = new TextEncoder().encode(payloadString);
+    let signParams = { name: 'ECDSA', hash: { name: 'SHA-256' } };
+    if (algoName && algoName.startsWith('RSA-PSS')) {
+      signParams = { name: 'RSA-PSS', saltLength: 32 };
+    }
+    const signatureBuffer = await subtle.sign(signParams, privateKey, data);
+    return bytesToBase64(new Uint8Array(signatureBuffer));
+  }
+
+  async function verifyClassical(payloadString, signatureBase64, publicJwkOrKey, algoName) {
+    const data = new TextEncoder().encode(payloadString);
+    const signatureBytes = base64ToBytes(signatureBase64);
+
+    let publicKey = publicJwkOrKey;
+    let importParams = { name: 'ECDSA', namedCurve: 'P-256' };
+    let verifyParams = { name: 'ECDSA', hash: { name: 'SHA-256' } };
+
+    if (algoName && algoName.startsWith('RSA-PSS')) {
+      importParams = { name: 'RSA-PSS', hash: 'SHA-256' };
+      verifyParams = { name: 'RSA-PSS', saltLength: 32 };
