+    return await subtle.verify(verifyParams, publicKey, signatureBytes, data);
+  }
+
+  // --- Quantum-Resistant Asymmetric Cryptography (W-OTS+ Hash-Based) ---
+  /**
+   * Post-Quantum Asymmetric Hash-Based Signature Scheme: W-OTS+ (Winternitz One-Time Signature Plus)
+   * Foundational to NIST FIPS 205 (SPHINCS+) and RFC 8391.
+   * Completely immune to Shor's algorithm as it relies strictly on collision/pre-image resistance of SHA-256.
+   */
+  const WOTS_W = 16; // base 16 nibbles
+  const WOTS_L1 = 64; // 32 bytes * 2 nibbles
+  const WOTS_L2 = 3;  // checksum nibbles
+  const WOTS_L = WOTS_L1 + WOTS_L2; // 67 total chains
+
+  async function hashChain(value, steps) {
+    let curr = value;
+    for (let i = 0; i < steps; i++) {
+      curr = await sha256(curr);
+    }
+    return curr;
+  }
+
+  async function generateQuantumResistantKeyPair() {
+    const privParts = [];
+    const pubParts = [];
+
+    for (let i = 0; i < WOTS_L; i++) {
+      const sk = new Uint8Array(32);
+      cryptoObj.getRandomValues(sk);
+      privParts.push(bytesToHex(sk));
+      const pk = await hashChain(sk, WOTS_W - 1);
+      pubParts.push(bytesToHex(pk));
+    }
+
+    const pubCombined = pubParts.join('');
+    const fpBytes = await sha256(new TextEncoder().encode(pubCombined));
+    const fingerprint = bytesToHex(fpBytes).substring(0, 16).toUpperCase();
+
+    return {
+      algorithm: 'W-OTS-PLUS-SHA256',
+      keyType: 'quantum-resistant',
+      keyId: 'DG-PQ-WOTS-' + fingerprint.substring(0, 8),
+      fingerprint,
+      publicKey: {
+        format: 'wots-plus-v1',
+        chains: pubParts
+      },
+      privateKey: {
+        format: 'wots-plus-v1',
+        chains: privParts
+      }
+    };
+  }
+
+  async function signQuantumResistant(payloadString, privateKeyData) {
+    const msgHash = await sha256(payloadString);
+    const nibbles = [];
+    let checksum = 0;
+
+    for (let i = 0; i < 32; i++) {
+      const n1 = (msgHash[i] >> 4) & 0x0f;
+      const n2 = msgHash[i] & 0x0f;
+      nibbles.push(n1, n2);
+      checksum += (15 - n1) + (15 - n2);
+    }
+    nibbles.push((checksum >> 8) & 0x0f);
+    nibbles.push((checksum >> 4) & 0x0f);
+    nibbles.push(checksum & 0x0f);
+
+    const sigParts = [];
+    for (let i = 0; i < WOTS_L; i++) {
+      const sk = hexToBytes(privateKeyData.chains[i]);
+      const sigChain = await hashChain(sk, nibbles[i]);
+      sigParts.push(bytesToHex(sigChain));
+    }
