+    return bytesToBase64(new TextEncoder().encode(JSON.stringify(sigParts)));
+  }
+
+  async function verifyQuantumResistant(payloadString, signatureBase64, publicKeyData) {
+    try {
+      const sigJson = new TextDecoder().decode(base64ToBytes(signatureBase64));
+      const sigParts = JSON.parse(sigJson);
+      if (!Array.isArray(sigParts) || sigParts.length !== WOTS_L) {
+        return false;
+      }
+
+      const msgHash = await sha256(payloadString);
+      const nibbles = [];
+      let checksum = 0;
+
+      for (let i = 0; i < 32; i++) {
+        const n1 = (msgHash[i] >> 4) & 0x0f;
+        const n2 = msgHash[i] & 0x0f;
+        nibbles.push(n1, n2);
+        checksum += (15 - n1) + (15 - n2);
+      }
+      nibbles.push((checksum >> 8) & 0x0f);
+      nibbles.push((checksum >> 4) & 0x0f);
+      nibbles.push(checksum & 0x0f);
