+        }
+      }
+      return true;
+    } catch (e) {
+      return false;
+    }
+  }
+
+  // --- High-Level Signing & Verification APIs for Coffee Receipts & Gift Vouchers ---
+
+  /**
+   * Signs a Coffee Order Receipt using either Classical or Quantum-Resistant Asymmetric Key
