+   * Universal Verifier: Verifies authenticity & integrity for both Receipts and Vouchers
+   */
+  async function verifyDocument(signedDocument, overridePublicKey = null) {
+    const startTime = (typeof performance !== 'undefined' ? performance.now() : Date.now());
+
+    let doc = signedDocument;
+    if (typeof doc === 'string') {
+      try {
+        doc = JSON.parse(doc);
+      } catch (err) {
+        return {
+          valid: false,
+          error: 'Document is not valid JSON: ' + err.message,
+          verificationTimeMs: 0
+        };
+      }
+    }
+
+    if (!doc || !doc.payload || !doc.signature || !doc.signature.value) {
+      return {
+        valid: false,
+        error: 'Invalid document structure: Missing payload or signature envelope',
+        verificationTimeMs: 0
+      };
+    }
