+    const canonicalPayload = canonicalizeJSON(doc.payload);
+    const computedDigestBytes = await sha256(canonicalPayload);
+    const computedDigestHex = bytesToHex(computedDigestBytes);
+
+    const algo = doc.signature.algorithm || 'ECDSA-P256-SHA256';
+    const isQuantum = doc.signature.keyType === 'quantum-resistant' || algo.includes('W-OTS');
