+    try {
+      if (isQuantum) {
+        isValid = await verifyQuantumResistant(canonicalPayload, doc.signature.value, pubKey);
+      } else {
+        isValid = await verifyClassical(canonicalPayload, doc.signature.value, pubKey, algo);
+      }
+    } catch (e) {
+      isValid = false;
+      verificationError = e.message;
+    }
+
+    const endTime = (typeof performance !== 'undefined' ? performance.now() : Date.now());
+    const duration = parseFloat((endTime - startTime).toFixed(2));
+
+    const digestMatches = (computedDigestHex === doc.canonicalDigestSha256);
+
+    return {
+      valid: isValid,
+      documentType: doc.type || 'unknown',
+      algorithm: algo,
+      keyType: isQuantum ? 'quantum-resistant' : 'classical',
+      keyId: doc.signature.keyId || 'N/A',
+      keyFingerprint: doc.signature.keyFingerprint || 'N/A',
+      computedDigestSha256: computedDigestHex,
+      originalDigestSha256: doc.canonicalDigestSha256 || 'N/A',
+      digestMatches,
+      verificationTimeMs: duration,
+      error: isValid ? null : (verificationError || 'Cryptographic signature mismatch! Document content has been tampered with or key is invalid.'),
+      payload: doc.payload
+    };
+  }
+
+  // --- Predefined Authority Key Management ---
+  let activeAuthorityKeyPair = null;
+
+  async function initializeAuthorityKeys(algorithm = 'ECDSA-P256') {
+    if (algorithm.includes('W-OTS')) {
+      activeAuthorityKeyPair = await generateQuantumResistantKeyPair();
+    } else if (algorithm.includes('RSA')) {
+      activeAuthorityKeyPair = await generateClassicalKeyPair('RSA-PSS-2048');
+    } else {
+      activeAuthorityKeyPair = await generateClassicalKeyPair('ECDSA-P256');
+    }
+    return activeAuthorityKeyPair;
+  }
+
+  function getActiveAuthorityKeyPair() {
+    return activeAuthorityKeyPair;
+  }
+
+  return {
+    canonicalizeJSON,
+    sha256,
+    bytesToHex,
+    hexToBytes,
+    bytesToBase64,
+    base64ToBytes,
+    generateClassicalKeyPair,
+    generateQuantumResistantKeyPair,
+    signCoffeeReceipt,
+    signGiftVoucher,
+    verifyDocument,
+    initializeAuthorityKeys,
+    getActiveAuthorityKeyPair,
+    CLASSICAL_ALGORITHMS
+  };
+});
