+          // Position updates
+          b.x += b.vx * dt;
+          b.y += b.vy * dt;
+          b.angle += b.vAngle * dt;
+        }
+
+        // Bean-bean soft collision & anti-clustering
+        for (var i1 = 0; i1 < beans.length; i1++) {
+          for (var i2 = i1 + 1; i2 < beans.length; i2++) {
+            var b1 = beans[i1];
+            var b2 = beans[i2];
+            var bdx = b2.x - b1.x;
+            var bdy = b2.y - b1.y;
+            var minD = (b1.size + b2.size) * 0.82;
+            var distSq = bdx * bdx + bdy * bdy;
+            if (distSq < minD * minD && distSq > 0.04) {
+              var d = Math.sqrt(distSq);
+              var push = (minD - d) * 0.5;
+              var bnx = bdx / d;
+              var bny = bdy / d;
+              b1.x -= bnx * push;
+              b1.y -= bny * push;
+              b2.x += bnx * push;
+              b2.y += bny * push;
+              b1.vx -= bnx * 15;
+              b1.vy -= bny * 15;
+              b2.vx += bnx * 15;
+              b2.vy += bny * 15;
+            }
+          }
+        }
+      }
+
+      function render() {
+        if (canvasWidth === 0 || canvasHeight === 0) return;
+        ctx.save();
+        ctx.scale(dpr, dpr);
+
+        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
