+        // Clip to drum window
+        ctx.save();
+        ctx.beginPath();
+        ctx.arc(cx, cy, radius, 0, Math.PI * 2);
+        ctx.clip();
+
+        // Drum chamber gradient
+        var drumGrad = ctx.createRadialGradient(cx, cy + radius * 0.35, radius * 0.1, cx, cy, radius);
+        drumGrad.addColorStop(0, '#3a1f14');
+        drumGrad.addColorStop(0.65, '#1e0f09');
+        drumGrad.addColorStop(1, '#0e0604');
+        ctx.fillStyle = drumGrad;
+        ctx.fillRect(cx - radius, cy - radius, radius * 2, radius * 2);
+
+        // Rotating drum vanes
+        ctx.save();
+        ctx.translate(cx, cy);
+        ctx.rotate(drumAngle);
+        ctx.strokeStyle = 'rgba(255, 171, 64, 0.09)';
+        ctx.lineWidth = 3.5;
+        for (var v = 0; v < 4; v++) {
+          var va = (v * Math.PI) / 2;
+          ctx.beginPath();
+          ctx.moveTo(Math.cos(va) * (radius * 0.15), Math.sin(va) * (radius * 0.15));
+          ctx.lineTo(Math.cos(va) * (radius * 0.94), Math.sin(va) * (radius * 0.94));
+          ctx.stroke();
+        }
+        ctx.restore();
+
+        // Hot burner radiant glow at bottom
+        var burnerGlow = ctx.createRadialGradient(cx, cy + radius * 0.95, radius * 0.05, cx, cy + radius * 0.8, radius * 0.7);
+        burnerGlow.addColorStop(0, 'rgba(255, 120, 20, 0.28)');
+        burnerGlow.addColorStop(0.5, 'rgba(255, 60, 0, 0.10)');
+        burnerGlow.addColorStop(1, 'rgba(255, 60, 0, 0)');
+        ctx.fillStyle = burnerGlow;
+        ctx.fillRect(cx - radius, cy - radius, radius * 2, radius * 2);
+
+        // Smoke particles
+        for (var pIdx = 0; pIdx < particles.length; pIdx++) {
+          var p = particles[pIdx];
+          if (p.alpha > 0.01) {
+            ctx.fillStyle = 'rgba(235, 215, 205, ' + p.alpha.toFixed(3) + ')';
+            ctx.beginPath();
+            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
+            ctx.fill();
+          }
+        }
+
+        // Draw coffee beans
+        for (var bIdx = 0; bIdx < beans.length; bIdx++) {
+          drawBean(beans[bIdx]);
+        }
+
+        ctx.restore(); // end clip
+
+        // Drum sight glass metal rim
+        ctx.lineWidth = Math.max(7, radius * 0.07);
+        ctx.strokeStyle = '#3e2723';
+        ctx.beginPath();
+        ctx.arc(cx, cy, radius, 0, Math.PI * 2);
+        ctx.stroke();
+
+        // Inner brass rim
+        ctx.lineWidth = 2;
+        ctx.strokeStyle = 'rgba(255, 171, 64, 0.45)';
+        ctx.beginPath();
+        ctx.arc(cx, cy, radius - 2, 0, Math.PI * 2);
+        ctx.stroke();
+
+        // Glass reflection sheen
+        var sheen = ctx.createLinearGradient(cx - radius * 0.7, cy - radius * 0.7, cx + radius * 0.4, cy + radius * 0.4);
