+
+        ctx.restore();
+      }
+
+      // Lifecycle controls
+      function startSimulator() {
+        if (isRunning) return;
+        isRunning = true;
+
+        if (engineStatusEl) {
+          engineStatusEl.textContent = 'Running';
+          engineStatusEl.className = 'roast-stat-val active-status';
+        }
+        if (pulseDotEl) {
+          pulseDotEl.className = 'roast-pulse-dot';
+        }
+
+        resizeCanvas();
+
+        var lastTime = (window.performance && window.performance.now) ? window.performance.now() : Date.now();
+        function loop(now) {
+          if (!isRunning) return;
+          var current = now || ((window.performance && window.performance.now) ? window.performance.now() : Date.now());
+          var dt = Math.min((current - lastTime) / 1000, 0.1);
+          lastTime = current;
+
+          updatePhysics(dt);
+          render();
+          animId = reqAnim(loop);
+        }
+        animId = reqAnim(loop);
+
+        if (!tempTimerId) {
+          updateTemperature();
+          tempTimerId = setInterval(updateTemperature, 1000);
+        }
+      }
+
+      function stopSimulator() {
+        if (!isRunning) return;
+        isRunning = false;
+
+        if (engineStatusEl) {
+          engineStatusEl.textContent = 'Standby (Paused)';
+          engineStatusEl.className = 'roast-stat-val paused-status';
+        }
+        if (pulseDotEl) {
+          pulseDotEl.className = 'roast-pulse-dot paused';
+        }
+
+        if (animId) {
+          cancelAnim(animId);
+          animId = null;
+        }
+        if (tempTimerId) {
+          clearInterval(tempTimerId);
+          tempTimerId = null;
+        }
+      }
