+      var hasNativeIntersectionObserver = (
+        typeof IntersectionObserver !== 'undefined' &&
+        typeof IntersectionObserverEntry !== 'undefined' &&
+        'isIntersecting' in IntersectionObserverEntry.prototype
+      );
