+    if (statusText) {
+      statusText.textContent = this._getRatingLabel(effectiveVal);
+      statusText.classList.toggle('has-value', effectiveVal > 0);
+    }
+  }
+
+  _render() {
+    const starSvg = `
+      <svg class="star-icon" viewBox="0 0 24 24" width="28" height="28" aria-hidden="true" focusable="false">
+        <path class="star-fill" d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/>
+      </svg>
+    `;
+
+    let starsHtml = '';
+    for (let i = 1; i <= this._max; i++) {
+      const isSelected = i === this._value;
+      const tabIndex = (!this._disabled && ((this._value === 0 && i === 1) || isSelected)) ? '0' : '-1';
+      const disabledAttr = this._disabled ? 'disabled' : '';
+      starsHtml += `
+        <button
+          type="button"
+          role="radio"
+          class="star-btn ${i <= this._value ? 'filled' : ''}"
+          data-value="${i}"
+          aria-label="${i} of ${this._max} stars"
+          aria-checked="${isSelected ? 'true' : 'false'}"
+          tabindex="${tabIndex}"
+          ${disabledAttr}
+        >
+          ${starSvg}
+        </button>
+      `;
+    }
+
+    this.shadowRoot.innerHTML = `
+      <style>
+        :host {
+          display: inline-block;
+          font-family: inherit;
+          user-select: none;
+        }
+
+        :host([hidden]) {
+          display: none;
+        }
+
+        .rating-widget {
+          display: inline-flex;
+          flex-direction: column;
+          gap: 6px;
+        }
+
+        .rating-widget.disabled {
+          opacity: 0.55;
+          cursor: not-allowed;
+          pointer-events: none;
+        }
+
+        .stars-container {
+          display: inline-flex;
+          align-items: center;
+          gap: 6px;
+        }
+
+        .star-btn {
+          background: transparent;
+          border: 1px solid transparent;
+          border-radius: 6px;
+          padding: 4px;
+          margin: 0;
+          cursor: pointer;
+          display: inline-flex;
+          align-items: center;
+          justify-content: center;
+          color: #d7ccc8;
+          transition: transform 0.15s ease, color 0.15s ease;
+          line-height: 0;
+        }
+
+        .star-btn:focus-visible {
+          outline: 2px solid #ffab40;
+          outline-offset: 2px;
+          background-color: rgba(255, 171, 64, 0.12);
+        }
+
+        .star-btn:not(:disabled):hover {
+          transform: scale(1.18);
+        }
+
+        .star-btn:not(:disabled):active {
+          transform: scale(0.95);
+        }
+
+        .star-icon {
+          width: 30px;
+          height: 30px;
+          display: block;
+          stroke: #8d6e63;
+          stroke-width: 1.2;
+          fill: #f5f5f5;
+          transition: fill 0.15s ease, stroke 0.15s ease, filter 0.15s ease;
+        }
+
+        .star-btn.filled .star-icon,
+        .star-btn.hovered .star-icon {
+          fill: #ffab40;
+          stroke: #e65100;
+          filter: drop-shadow(0 1px 3px rgba(255, 171, 64, 0.4));
+        }
+
+        .star-btn.hovered:not(.filled) .star-icon {
+          fill: #ffd54f;
+          stroke: #ffab40;
+        }
+
+        .rating-status-text {
+          font-size: 0.88rem;
+          color: #5d4037;
+          font-weight: 500;
+          min-height: 1.3em;
+          transition: color 0.2s ease;
+        }
+
+        .rating-status-text.has-value {
+          color: #3e2723;
+          font-weight: 600;
+        }
+      </style>
+      <div class="rating-widget ${this._disabled ? 'disabled' : ''}" ${this._disabled ? 'aria-disabled="true"' : ''}>
+        <div class="stars-container" role="radiogroup" aria-label="Coffee star rating">
+          ${starsHtml}
+        </div>
+        <div class="rating-status-text ${this._value > 0 ? 'has-value' : ''}" aria-live="polite">
+          ${this._getRatingLabel(this._value)}
+        </div>
+      </div>
+    `;
+
+    // Attach event listeners
+    const container = this.shadowRoot.querySelector('.stars-container');
+    const buttons = this.shadowRoot.querySelectorAll('.star-btn');
+
+    buttons.forEach(btn => {
+      const val = parseInt(btn.getAttribute('data-value'), 10);
+
+      btn.addEventListener('pointerenter', () => {
+        if (this._disabled) return;
+        this._hoverValue = val;
+        this._updateDisplay();
+      });
+
+      btn.addEventListener('click', (e) => {
+        e.preventDefault();
+        this._selectStar(val);
+      });
+
+      btn.addEventListener('keydown', (e) => {
+        this._handleKeyDown(e, val);
+      });
+    });
+
+    container.addEventListener('pointerleave', () => {
+      if (this._disabled) return;
+      this._hoverValue = 0;
+      this._updateDisplay();
+    });
+  }
+}
+
+if (!customElements.get('star-rating')) {
+  customElements.define('star-rating', StarRating);
+}
+
+if (typeof module !== 'undefined' && module.exports) {
+  module.exports = { StarRating };
+}

