+    if (clean === 'order-online' || clean === 'order') return 'order-online';
+    if (clean === 'logout') return 'logout';
+    if (clean === 'about') return 'about';
+    if (clean === 'careers') return 'careers';
+    if (clean === 'contact') return 'contact';
+    if (clean === 'privacy-policy' || clean === 'privacy') return 'privacy';
+    return 'home';
+  }
+
+  function getItemKeyFromHrefOrTitle(href, title) {
+    const h = (href || '').toLowerCase();
+    const t = (title || '').toLowerCase();
+    if (h.includes('seasonal') || t.includes('maple') || t.includes('latte')) return 'maple-oat-latte';
+    if (h.includes('espresso') || t.includes('espresso') || t.includes('dark roast')) return 'dark-roast-espresso';
+    if (h.includes('cold-brew') || t.includes('cold brew')) return 'cold-brew';
+    return 'maple-oat-latte';
+  }
+
+  /**
+   * Switches client-side view and measures time to finish painting visual updates.
+   */
+  function switchView(viewName, options = {}) {
+    const targetView = views[viewName] ? viewName : 'home';
+
+    return measureInteraction('view-switch', targetView, targetView, () => {
+      currentView = targetView;
+
+      // Update Nav active classes
+      document.querySelectorAll('nav a').forEach((a) => {
+        const href = a.getAttribute('href');
+        if (href && pathToView(href) === targetView) {
+          a.classList.add('active');
+        } else {
+          a.classList.remove('active');
+        }
+      });
+
+      // Update browser history if supported
+      try {
+        const newPath = targetView === 'home' ? '/' : `/${targetView}`;
+        if (window.location && window.location.pathname !== newPath) {
+          history.pushState({ view: targetView }, '', newPath);
+        }
+      } catch (e) {}
+
+      // Update Hero
+      renderHero(targetView, options);
+
+      // Render view content into container
+      const main = document.querySelector('main.container');
+      if (main) {
+        main.innerHTML = views[targetView](options);
+      }
+
+      // Update document title
+      const titleMap = {
+        home: 'The Daily Grind | Artisanal Coffee',
+        menu: 'Artisanal Menu | The Daily Grind',
+        locations: 'Our Locations | The Daily Grind',
+        rewards: 'Rewards Club | The Daily Grind',
+        account: 'My Account | The Daily Grind',
+        'order-online': 'Order Online | The Daily Grind',
+        'seasonal-detail': 'Seasonal Feature | The Daily Grind',
+        logout: 'Logged Out | The Daily Grind',
+        about: 'Our Story | The Daily Grind',
+        careers: 'Join The Team | The Daily Grind',
+        contact: 'Contact Us | The Daily Grind',
+        privacy: 'Privacy Policy | The Daily Grind'
+      };
+      document.title = titleMap[targetView] || 'The Daily Grind | Artisanal Coffee';
+
+      try {
+        window.scrollTo(0, 0);
+      } catch (e) {}
+    });
+  }
+
+  function navigateTo(path) {
+    const view = pathToView(path);
+    const opts = {};
+    if (path && path.startsWith('/menu/')) {
+      opts.item = getItemKeyFromHrefOrTitle(path, '');
+    }
+    return switchView(view, opts);
+  }
+
+  /**
+   * Set up global click interception and performance measurement
+   */
+  function setupInteractionListeners() {
+    document.addEventListener('click', function (e) {
+      // 1. Navigation bar click
+      const navElement = e.target.closest('nav');
+      if (navElement) {
+        const navLink = e.target.closest('a');
+        const isLogo = e.target.closest('.logo');
+        const targetLabel = navLink
+          ? (navLink.textContent || navLink.getAttribute('href')).trim()
+          : (isLogo ? 'Logo' : 'Navbar');
+        const href = navLink ? navLink.getAttribute('href') : (isLogo ? '/' : null);
+
+        if (href) {
+          e.preventDefault();
+          const view = pathToView(href);
+
+          measureInteraction('navigation-bar', targetLabel, navLink || navElement, () => {
+            navElement.querySelectorAll('a').forEach((a) => a.classList.remove('active'));
+            if (navLink) navLink.classList.add('active');
+            navElement.classList.add('nav-active-feedback');
+            setTimeout(() => navElement.classList.remove('nav-active-feedback'), 300);
+
+            switchView(view);
+          });
+          return;
+        } else {
+          // Click on nav element background
+          measureInteraction('navigation-bar', targetLabel, navElement, () => {
+            navElement.classList.add('nav-active-feedback');
+            setTimeout(() => navElement.classList.remove('nav-active-feedback'), 300);
+          });
+          return;
+        }
+      }
+
+      // 2. "Seasonal Favorites" cards
+      const seasonalCard = e.target.closest('.card, [data-seasonal-card]');
+      if (seasonalCard) {
+        e.preventDefault();
+        const titleEl = seasonalCard.querySelector('h3');
+        const title = titleEl ? titleEl.textContent.trim() : 'Seasonal Item';
+        const linkEl = seasonalCard.querySelector('a');
+        const href = linkEl ? linkEl.getAttribute('href') : '/menu/seasonal';
+        const itemKey = getItemKeyFromHrefOrTitle(href, title);
+
+        measureInteraction('seasonal-favorites', title, seasonalCard, () => {
+          seasonalCard.classList.add('card-active');
+          setTimeout(() => seasonalCard.classList.remove('card-active'), 400);
+          switchView('seasonal-detail', { item: itemKey });
+        });
+        return;
+      }
+
+      // 3. "Order Now" button
+      const orderBtn = e.target.closest('.hero .btn, a[href="/order-online"], [data-action="order-now"]');
+      const isOrderText = e.target.closest('.btn') && e.target.textContent && e.target.textContent.toLowerCase().includes('order now');
+      if (orderBtn || isOrderText) {
+        e.preventDefault();
+        const btn = orderBtn || e.target.closest('.btn');
+        const label = btn && btn.textContent ? btn.textContent.trim() : 'Order Now';
+
+        measureInteraction('order-now', label, btn, () => {
+          btn.style.transform = 'scale(0.97)';
+          setTimeout(() => { if (btn) btn.style.transform = ''; }, 150);
+          switchView('order-online');
+        });
+        return;
+      }
+
+      // 4. Other internal links
+      const anyLink = e.target.closest('a[href^="/"]');
+      if (anyLink) {
+        const href = anyLink.getAttribute('href');
+        if (href && !href.startsWith('//') && !href.startsWith('http')) {
+          e.preventDefault();
+          const view = pathToView(href);
+          const opts = {};
+          if (href.startsWith('/menu/')) {
+            opts.item = getItemKeyFromHrefOrTitle(href, anyLink.textContent);
+          }
+          switchView(view, opts);
+        }
+      }
+    }, true);
+
+    // Browser back/forward navigation
+    window.addEventListener('popstate', () => {
+      const path = (window.location && (window.location.pathname || window.location.hash)) || '/';
+      const view = pathToView(path);
+      const opts = {};
+      if (path.startsWith('/menu/')) {
+        opts.item = getItemKeyFromHrefOrTitle(path, '');
+      }
+      switchView(view, opts);
+    });
+  }
+
+  // Create performance monitor API object
+  const performanceMonitor = {
+    metrics: metrics,
+    getMetrics: function (category) {
+      if (!category) return this.metrics.slice();
+      const catLower = category.toLowerCase();
+      return this.metrics.filter((m) =>
+        m.category.toLowerCase() === catLower ||
+        m.name.toLowerCase().includes(catLower)
+      );
+    },
+    getLatestMetric: function (category) {
+      const list = this.getMetrics(category);
+      return list.length ? list[list.length - 1] : null;
+    },
+    clearMetrics: function () {
+      this.metrics.length = 0;
+      try {
+        perf.clearMarks();
+        perf.clearMeasures();
+      } catch (e) {}
+    },
+    switchView: function (viewName, options) {
+      return switchView(viewName, options);
+    },
+    navigateTo: function (path) {
+      return navigateTo(path);
+    },
+    measureInteraction: function (category, name, target, actionFn) {
+      return measureInteraction(category, name, target, actionFn);
+    },
+    waitForNextPaint: function (callback) {
+      return waitForNextPaint(callback);
+    },
+    afterNextPaint: function (callback) {
+      return waitForNextPaint(callback);
+    },
+    getCurrentView: function () {
+      return currentView;
+    }
+  };
+
+  // Expose global variables
+  window.performanceMonitor = performanceMonitor;
+  window.performanceMetrics = metrics;
+  window.__performanceMetrics = metrics;
+  window.__perfMetrics = metrics;
+  window.__performanceMonitor = performanceMonitor;
+  window.switchView = switchView;
+  window.navigateTo = navigateTo;
+
+  // Initialize once DOM is ready
+  function init() {
+    setupInteractionListeners();
+
+    // Check if initial URL points to a specific view
+    try {
+      const path = window.location.pathname || window.location.hash || '/';
+      if (path && path !== '/' && path !== '/index.html' && path !== '#') {
+        const initialView = pathToView(path);
+        if (initialView !== 'home') {
+          const opts = {};
+          if (path.startsWith('/menu/')) {
+            opts.item = getItemKeyFromHrefOrTitle(path, '');
+          }
+          switchView(initialView, opts);
+        }
+      }
+    } catch (e) {}
+  }
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', init);
+  } else {
+    init();
+  }
+
+  return performanceMonitor;
+});

