+        Developer Diagnostics Connection Lab
+      </h1>
+      <p class="text-gray-600 text-sm mt-2 max-w-3xl leading-relaxed">
+        Connect directly from your browser to hardware test devices located on your private Wi-Fi LAN
+        (e.g., <code class="font-mono bg-gray-100 px-1 py-0.5 rounded text-gray-800">192.168.1.x</code>) and your
+        local companion CLI daemon (e.g., <code class="font-mono bg-gray-100 px-1 py-0.5 rounded text-gray-800">127.0.0.1</code>)
+        leveraging Chromium's Local Network Access (LNA) and Private Network Access (PNA) specifications.
+      </p>
+    </div>
+
+    <!-- Main Diagnostics Widget -->
+    <DeveloperDiagnosticsWidget client:load />
+
+    <!-- Companion CLI & Hardware Setup Guides -->
+    <div class="mt-12 grid grid-cols-1 md:grid-cols-2 gap-8 border-t border-gray-300 pt-8 text-xs text-gray-700">
+      <div class="bg-gray-50 border border-gray-200 rounded-lg p-5">
+        <h2 class="text-base font-bold text-gray-900 mb-2 flex items-center gap-2">
+          <span>Local Companion CLI Setup (127.0.0.1)</span>
+        </h2>
+        <p class="mb-3 text-gray-600">
+          Run this minimal Node.js server to act as your companion daemon responding to browser loopback requests:
+        </p>
+        <pre class="bg-gray-900 text-gray-100 p-3 rounded font-mono text-[11px] overflow-x-auto"><code>{`// companion-cli.mjs
+import http from 'node:http';
+
+const server = http.createServer((req, res) => {
+  // Required CORS & PNA response headers
+  res.setHeader('Access-Control-Allow-Origin', '*');
+  res.setHeader('Access-Control-Allow-Private-Network', 'true');
+  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
+  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
+
+  if (req.method === 'OPTIONS') {
+    res.writeHead(204);
+    res.end();
+    return;
+  }
+
+  res.writeHead(200, { 'Content-Type': 'application/json' });
+  res.end(JSON.stringify({
+    cliVersion: 'devtools-companion v1.14.2',
+    pid: process.pid,
+    activeSession: 'sess_' + Math.random().toString(36).slice(2, 10),
+    activeWorkers: 2,
+    memoryUsage: (process.memoryUsage().rss / 1024 / 1024).toFixed(1) + ' MB',
+    gitBranch: 'main @ HEAD',
+    daemonUptime: Math.floor(process.uptime()) + 's'
+  }));
+});
+
+server.listen(8765, '127.0.0.1', () => {
+  console.log('Companion CLI listening on http://127.0.0.1:8765');
+});`}</code></pre>
