+
+        const action = actionBtn.dataset.action;
+        const name = actionBtn.dataset.name || actionBtn.dataset.drink || 'Item';
+        const price = actionBtn.dataset.price || '';
+
+        switch (action) {
+          case 'order-drink':
+            showToast(`Added ${name} (${price}) to your order!`);
+            closeRootMenu(actionBtn, { fromPointer: event.detail > 0 });
+            break;
+          case 'quick-order':
+            showToast(`Quick order placed for ${name}!`);
+            closeRootMenu(actionBtn, { fromPointer: event.detail > 0 });
+            break;
+          case 'favorite-drink':
+            showToast(`Saved ${name} to your Favorites!`);
+            closeRootMenu(actionBtn, { fromPointer: event.detail > 0 });
+            break;
+          case 'switch-card':
+            showToast(`Switched selection to ${name}`);
+            closeRootMenu(actionBtn, { fromPointer: event.detail > 0 });
+            break;
+          case 'quick-reorder':
+            showToast(`Reordering your recent favorites!`);
+            closeRootMenu(actionBtn, { fromPointer: event.detail > 0 });
+            break;
+          case 'select-nav-drink':
+            showToast(`Viewing drink: ${name}`);
+            closeRootMenu(actionBtn, { fromPointer: event.detail > 0 });
+            break;
+          case 'view-nutrition':
+            showToast('Loading Nutritional & Allergen guide...');
+            closeRootMenu(actionBtn, { fromPointer: event.detail > 0 });
+            break;
+          case 'catering':
+            showToast('Opening Catering & Events form...');
+            closeRootMenu(actionBtn, { fromPointer: event.detail > 0 });
+            break;
+          case 'view-details':
+            showToast(`Viewing details for ${name}`);
+            closeRootMenu(actionBtn, { fromPointer: event.detail > 0 });
+            break;
+        }
+      });
+
+      // Initialize all card summaries
+      ['card1', 'card2', 'card3'].forEach(updateCardSummary);
+    })();
+  </script>
 </body>

