+import React, { useState, useEffect } from 'react';
+import {
+  FingerPrintIcon,
+  KeyIcon,
+  TrashIcon,
+  PencilSquareIcon,
+  CheckIcon,
+  XMarkIcon,
+  ShieldCheckIcon,
+  ComputerDesktopIcon,
+  DevicePhoneMobileIcon,
+  UserIcon,
+  ArrowPathIcon,
+} from '@heroicons/react/24/outline';
+import {
+  type Passkey,
+  type ReaderProfile,
+  type SignalLogEntry,
+  type SignalCapabilities,
+  getWebAuthnSignalCapabilities,
+  signalUserDetailsSync,
+  signalPasskeyRemovalSync,
+  signalAllAcceptedCredentialsSync,
+  createPasskeyWithBrowser,
+} from '../utils/webauthnSignals';
+
+export default function AccountSettings() {
+  const [user, setUser] = useState<ReaderProfile>({
+    userId: 'dXNlcl9kZXZ0b29sc19yZWFkZXI',
+    username: 'reader@devtoolstimes.com',
+    displayName: 'DevTools Reader',
+  });
+  const [passkeys, setPasskeys] = useState<Passkey[]>([]);
+  const [loading, setLoading] = useState(true);
+  const [capabilities, setCapabilities] = useState<SignalCapabilities>({
+    supported: false,
+    signalAllAcceptedCredentials: false,
+    signalCurrentUserDetails: false,
+    signalUnknownCredential: false,
+  });
+
+  // User display name editing state
+  const [isEditingUserDisplayName, setIsEditingUserDisplayName] = useState(false);
+  const [userDisplayNameInput, setUserDisplayNameInput] = useState('');
+  const [savingUserDisplayName, setSavingUserDisplayName] = useState(false);
+
+  // Passkey inline editing state: passkeyId -> new display name input
+  const [editingPasskeyId, setEditingPasskeyId] = useState<string | null>(null);
+  const [passkeyNameInput, setPasskeyNameInput] = useState('');
+  const [savingPasskeyName, setSavingPasskeyName] = useState(false);
+
+  // Passkey removal confirmation state
+  const [confirmRemoveId, setConfirmRemoveId] = useState<string | null>(null);
+  const [removingPasskey, setRemovingPasskey] = useState(false);
+
+  // Add passkey modal / state
+  const [isAddingPasskey, setIsAddingPasskey] = useState(false);
+  const [newPasskeyName, setNewPasskeyName] = useState('');
+  const [creatingPasskey, setCreatingPasskey] = useState(false);
+
+  // Notification message
+  const [notification, setNotification] = useState<{
+    type: 'success' | 'info' | 'error';
+    message: string;
+    details?: string;
+  } | null>(null);
+
+  // Signal activity log
+  const [signalLogs, setSignalLogs] = useState<SignalLogEntry[]>([]);
+  const [isManualSyncing, setIsManualSyncing] = useState(false);
+
+  const baseUrl = import.meta.env.BASE_URL || '/';
+
+  // Load initial data
+  useEffect(() => {
+    async function loadData() {
+      setLoading(true);
+      try {
+        // Detect WebAuthn signal capabilities
+        const caps = await getWebAuthnSignalCapabilities();
+        setCapabilities(caps);
+
+        // Fetch from API
+        const res = await fetch(`${baseUrl}api/passkeys.json`);
+        if (res.ok) {
+          const data = await res.json();
+          if (data.user) {
+            // Check if localStorage has a signed-in user from sign-in form
+            const localUserStr = localStorage.getItem('user');
+            if (localUserStr) {
+              try {
+                const localUser = JSON.parse(localUserStr);
+                setUser({
+                  userId: localUser.userId || data.user.userId,
+                  username: localUser.username || data.user.username,
+                  displayName: localUser.displayName || data.user.displayName,
+                });
+                setUserDisplayNameInput(localUser.displayName || data.user.displayName);
+              } catch {
+                setUser(data.user);
+                setUserDisplayNameInput(data.user.displayName);
+              }
+            } else {
+              setUser(data.user);
+              setUserDisplayNameInput(data.user.displayName);
+            }
+          }
+          if (Array.isArray(data.passkeys)) {
+            setPasskeys(data.passkeys);
+          }
+        }
+      } catch (err) {
+        console.error('Failed to load passkeys:', err);
+      } finally {
+        setLoading(false);
+      }
+    }
+
+    loadData();
+  }, [baseUrl]);
+
+  // Dismiss notification after 6 seconds
+  useEffect(() => {
+    if (notification) {
+      const timer = setTimeout(() => setNotification(null), 6000);
+      return () => clearTimeout(timer);
+    }
+  }, [notification]);
+
+  // Handle Reader Display Name update
+  const handleSaveUserDisplayName = async () => {
+    if (!userDisplayNameInput.trim() || userDisplayNameInput === user.displayName) {
+      setIsEditingUserDisplayName(false);
+      return;
+    }
+
+    setSavingUserDisplayName(true);
+    const updatedUser: ReaderProfile = {
+      ...user,
+      displayName: userDisplayNameInput.trim(),
+    };
+
+    try {
+      // 1. Update on server session
+      const res = await fetch(`${baseUrl}api/passkeys.json`, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({
+          action: 'update_user_display_name',
+          displayName: updatedUser.displayName,
+        }),
+      });
+
+      if (res.ok) {
+        // Update local storage
+        localStorage.setItem('user', JSON.stringify(updatedUser));
+        setUser(updatedUser);
+
+        // 2. Synchronize with Browser Authenticator via WebAuthn Signal API
+        const log = await signalUserDetailsSync(updatedUser);
+        setSignalLogs((prev) => [log, ...prev]);
+
+        setNotification({
+          type: 'success',
+          message: 'Display name updated successfully.',
+          details:
+            log.status === 'sent'
+              ? 'Browser authenticator was notified via PublicKeyCredential.signalCurrentUserDetails to update stored passkey labels.'
+              : 'Saved locally. (Browser authenticator signaling skipped: not supported in this environment).',
+        });
+      } else {
+        setNotification({
+          type: 'error',
+          message: 'Failed to update display name on server.',
+        });
+      }
+    } catch (err: any) {
+      setNotification({
+        type: 'error',
+        message: 'An error occurred while updating display name.',
+        details: err?.message || String(err),
+      });
+    } finally {
+      setSavingUserDisplayName(false);
+      setIsEditingUserDisplayName(false);
+    }
+  };
+
+  // Handle Passkey Display Name update
+  const handleStartEditPasskey = (passkey: Passkey) => {
+    setEditingPasskeyId(passkey.id);
+    setPasskeyNameInput(passkey.displayName);
+  };
+
+  const handleSavePasskeyName = async (passkeyId: string) => {
+    if (!passkeyNameInput.trim()) {
+      setEditingPasskeyId(null);
+      return;
+    }
+
+    setSavingPasskeyName(true);
+    const trimmedName = passkeyNameInput.trim();
+
+    try {
+      const res = await fetch(`${baseUrl}api/passkeys.json`, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({
+          action: 'update_passkey_name',
+          id: passkeyId,
+          displayName: trimmedName,
+        }),
+      });
+
+      if (res.ok) {
+        setPasskeys((prev) =>
+          prev.map((k) => (k.id === passkeyId ? { ...k, displayName: trimmedName } : k))
+        );
+        setNotification({
+          type: 'success',
+          message: `Passkey display name updated to "${trimmedName}".`,
+        });
+      } else {
+        setNotification({
+          type: 'error',
+          message: 'Failed to update passkey display name.',
+        });
