+    isWebAuthnSupported,
+    detectDefaultDeviceName,
+    registerPasskey,
+    authenticatePasskey,
+    setAuthMode,
+    getAuthMode,
+    bufferToBase64URL,
+    base64URLToBuffer
+  };
+});
