+import type { APIRoute } from 'astro';
+import { passkeysDb } from '../../../utils/passkeysDb';
+
+export const POST: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json();
+    const { username, credentialId } = body;
+
+    if (!username || !credentialId) {
+      return new Response(JSON.stringify({ error: 'Username and credentialId are required' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    const success = passkeysDb.deletePasskey(username, credentialId);
+    if (!success) {
+      return new Response(JSON.stringify({ error: 'Passkey not found or could not be deleted' }), {
+        status: 404,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
