+
+    if (acceptAllBtn) {
+      acceptAllBtn.addEventListener('click', () => {
+        ConsentManager.acceptAll();
+        if (banner) banner.style.display = 'none';
+      });
+    }
+
+    if (rejectAllBtn) {
+      rejectAllBtn.addEventListener('click', () => {
+        ConsentManager.rejectAll();
+        if (banner) banner.style.display = 'none';
+      });
+    }
+
+    if (manageBtn) {
+      manageBtn.addEventListener('click', () => {
+        openPrivacyModal();
+      });
+    }
+
+    // Modal Triggers & Controls
+    window.openPrivacyModal = function () {
+      if (!modal) return;
+      const consent = ConsentManager.getConsent() || ConsentManager.getDefaultConsent();
+
+      const functionalToggle = document.getElementById('pref-functional');
+      const analyticsToggle = document.getElementById('pref-analytics');
+      const marketingToggle = document.getElementById('pref-marketing');
+
+      if (functionalToggle) functionalToggle.checked = Boolean(consent.functional);
+      if (analyticsToggle) {
+        analyticsToggle.checked = Boolean(consent.analytics);
+        analyticsToggle.disabled = detectGPC(); // Lock if GPC is active
+      }
+      if (marketingToggle) {
+        marketingToggle.checked = Boolean(consent.marketing);
+        marketingToggle.disabled = detectGPC(); // Lock if GPC is active
+      }
+
+      modal.style.display = 'flex';
+      modal.setAttribute('aria-hidden', 'false');
+    };
+
+    window.closePrivacyModal = function () {
+      if (!modal) return;
+      modal.style.display = 'none';
+      modal.setAttribute('aria-hidden', 'true');
+    };
+
+    const savePrefsBtn = document.getElementById('btn-save-preferences');
