+            <span class="stat-label">External Resources</span>
+          </div>
+          <div class="audit-stat">
+            <span class="stat-number" style="color: ${report.isCompliant ? '#2e7d32' : '#c62828'}">
+              ${report.isCompliant ? '100% Compliant' : 'Alerts Found'}
+            </span>
+            <span class="stat-label">CSP & PbD Status</span>
+          </div>
+          <div class="audit-stat">
+            <span class="stat-number" style="font-size: 1rem; color: #1565c0;">${report.gpcStatus}</span>
+            <span class="stat-label">GPC Signal</span>
+          </div>
+        </div>
+        <div class="audit-section">
+          <h4>Audited Third-Party Domains:</h4>
+          <ul>
+            ${report.thirdPartyDomains.length ? report.thirdPartyDomains.map(d => `<li><code>${d}</code> (Image CDN - No-Referrer Enforced)</li>`).join('') : '<li>No third-party domains detected.</li>'}
+          </ul>
+        </div>
+        <div class="audit-section">
+          <h4>Approved Origins Whitelist:</h4>
+          <ul>
+            ${APPROVED_ORIGINS.map(o => `<li><code>${o}</code></li>`).join('')}
+          </ul>
+        </div>
+        <div class="audit-section">
