+        </div>
+      `;
+    }
+
+    // Attach logout handlers to any logout links
+    document.querySelectorAll('a[href="/logout"], .logout-link').forEach(link => {
+      link.addEventListener('click', handleSecureLogout);
+    });
+  }
+
+  // Initialization lifecycle
+  sanitizeUrlParameters();
+  ThirdPartyAuditor.init();
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', () => {
+      initPrivacyUI();
+      initFormMinimization();
+    });
+  } else {
