@@ -0,0 +1,160 @@
+/**
+ * The Daily Grind - Production-Ready Secure Static Server (server.js)
+ *
+ * Implements Privacy by Design & Defense-in-Depth Security Headers:
+ * - Content-Security-Policy (CSP)
+ * - X-Content-Type-Options: nosniff
+ * - X-Frame-Options: DENY
+ * - Referrer-Policy: strict-origin-when-cross-origin
+ * - Permissions-Policy (Disables Geolocation, Camera, Microphone, FLoC/interest-cohort)
+ * - Strict-Transport-Security (HSTS)
+ * - Cross-Origin-Opener-Policy & Cross-Origin-Embedder-Policy (Cross-Origin Isolation)
+ * - Clear-Site-Data on /logout (purges browser cache, cookies, and local storage)
+ */
+
+import http from 'node:http';
+import fs from 'node:fs';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const __filename = fileURLToPath(import.meta.url);
+const __dirname = path.dirname(__filename);
+
+const PORT = parseInt(process.env.PORT || '11222', 10);
+const ROOT_DIR = __dirname;
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.mjs': 'application/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.webp': 'image/webp',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon',
+  '.txt': 'text/plain; charset=utf-8'
+};
+
+const SECURITY_HEADERS = {
+  'Content-Security-Policy': "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https://images.unsplash.com; font-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self';",
+  'X-Content-Type-Options': 'nosniff',
+  'X-Frame-Options': 'DENY',
+  'X-XSS-Protection': '0',
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'Permissions-Policy': 'accelerometer=(), camera=(), geolocation=(), gyroscope=(), magnetometer=(), microphone=(), payment=(), usb=(), interest-cohort=()',
+  'Strict-Transport-Security': 'max-age=63072000; includeSubDomains; preload',
+  'Cross-Origin-Opener-Policy': 'same-origin',
+  'Cross-Origin-Embedder-Policy': 'require-corp',
+  'Cross-Origin-Resource-Policy': 'same-origin',
+  'X-Permitted-Cross-Domain-Policies': 'none',
+  'Cache-Control': 'public, max-age=3600, must-revalidate'
+};
+
+function applySecurityHeaders(res) {
+  for (const [header, val] of Object.entries(SECURITY_HEADERS)) {
+    res.setHeader(header, val);
+  }
+}
+
+const server = http.createServer((req, res) => {
+  // Apply standard security headers to every response
+  applySecurityHeaders(res);
+
+  const reqUrl = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
+  const pathname = decodeURIComponent(reqUrl.pathname);
+
+  // Handle Logout Route: Clear-Site-Data (Privacy by Design session termination)
+  if (pathname === '/logout') {
+    res.setHeader('Clear-Site-Data', '"cache", "cookies", "storage"');
+    res.writeHead(302, { 'Location': '/?logged_out=1' });
+    res.end('Logged out successfully.');
+    return;
+  }
+
+  // Handle /privacy-policy route
+  if (pathname === '/privacy-policy') {
+    const policyPath = path.join(ROOT_DIR, 'privacy-policy.html');
+    if (fs.existsSync(policyPath)) {
+      res.setHeader('Content-Type', 'text/html; charset=utf-8');
+      fs.createReadStream(policyPath).pipe(res);
+      return;
+    }
+  }
+
+  // Handle Third-Party Audit API endpoint
+  if (pathname === '/api/privacy/audit') {
+    res.setHeader('Content-Type', 'application/json; charset=utf-8');
+    res.end(JSON.stringify({
+      status: 'success',
+      privacyFramework: 'Privacy by Design (ISO/IEC 27701)',
+      dataMinimization: true,
+      thirdPartyAudit: {
+        auditedDomains: ['self', 'https://images.unsplash.com'],
+        unapprovedTrackersCount: 0,
+        cspEnforced: true,
+        permissionsPolicyEnforced: true
+      },
+      headersApplied: SECURITY_HEADERS
+    }, null, 2));
+    return;
+  }
+
+  // Determine file path
+  let relativePath = pathname;
+  if (relativePath === '/' || relativePath === '') {
+    relativePath = '/index.html';
+  }
+
+  // Security: prevent directory traversal
+  const safePath = path.normalize(relativePath).replace(/^(\.\.[\/\\])+/, '');
+  let filePath = path.join(ROOT_DIR, safePath);
+
+  // If path is a directory, look for index.html
+  if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
+    filePath = path.join(filePath, 'index.html');
+  }
+
+  // If file doesn't exist but .html version exists (e.g. /menu -> /menu.html)
+  if (!fs.existsSync(filePath) && fs.existsSync(`${filePath}.html`)) {
+    filePath = `${filePath}.html`;
+  }
+
+  // If still not found, fallback to index.html for SPA routes or return 404
+  if (!fs.existsSync(filePath)) {
+    const indexPath = path.join(ROOT_DIR, 'index.html');
+    if (fs.existsSync(indexPath) && !path.extname(pathname)) {
+      filePath = indexPath;
+    } else {
+      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('404 Not Found');
+      return;
+    }
+  }
+
+  const ext = path.extname(filePath).toLowerCase();
+  const contentType = MIME_TYPES[ext] || 'application/octet-stream';
+
+  res.setHeader('Content-Type', contentType);
+
+  if (req.method === 'HEAD') {
+    res.writeHead(200);
+    res.end();
+    return;
+  }
+
+  const stream = fs.createReadStream(filePath);
+  stream.on('error', (err) => {
+    res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Internal Server Error');
+  });
+  stream.pipe(res);
+});
+
+server.listen(PORT, '0.0.0.0', () => {
+  console.log(`[Daily Grind] Privacy by Design Server listening on port ${PORT}`);
+});
+
+export default server;

