+// Daily Grind - Custom Node.js Server with Connection-Allowlist & CSP Security Headers
+import http from 'node:http';
+import fs from 'node:fs';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const __filename = fileURLToPath(import.meta.url);
+const __dirname = path.dirname(__filename);
+
+export const ALLOWLIST_DESTS = new Set([
+  'document',
+  'iframe',
+  'worker',
+  'sharedworker',
+  'serviceworker',
+]);
+
+/**
+ * Normalizes a URLPattern string for Connection-Allowlist per RFC 9651.
+ * Rewrites ws:// and wss:// to http:// and https:// and strips bare trailing slashes.
+ */
+export function normalizeAllowlistPattern(rawPattern) {
+  const trimmed = String(rawPattern).trim().replace(/^ws(s?):\/\//i, 'http$1://');
+  if (!/^https?:\/\//i.test(trimmed)) {
+    throw new Error(`Pattern must include an http:// or https:// scheme: ${rawPattern}`);
+  }
+  if (/[\s,]/.test(trimmed)) {
+    throw new Error(`Pattern must be a single URLPattern without spaces or commas: ${rawPattern}`);
+  }
+  if (/[()]/.test(trimmed)) {
+    throw new Error(`Custom regex groups are rejected by Connection-Allowlist: ${rawPattern}`);
+  }
+  return trimmed.replace(/^(https?:\/\/[^/?#]+)\/$/i, '$1');
+}
+
+/**
+ * Builds an RFC 9651 Inner List header value for Connection-Allowlist.
+ */
+export function buildConnectionAllowlistHeader({
+  allowSelf = true,
+  patterns = [],
+  reportTo,
+  redirects = 'block',
+  webrtc = 'block',
+} = {}) {
+  const items = allowSelf ? ['response-origin'] : [];
+  for (const pattern of patterns) {
+    const raw = String(pattern).trim();
+    if (raw === 'response-origin') {
+      if (!items.includes('response-origin')) items.push('response-origin');
+      continue;
+    }
+    const normalized = normalizeAllowlistPattern(raw);
+    items.push(`"${normalized.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`);
+  }
+  let header = `(${items.join(' ')})`;
+  if (redirects === 'allow') header += '; redirects=allow';
+  if (webrtc === 'allow') header += '; webrtc=allow';
+  if (reportTo) {
+    const endpointToken = String(reportTo).trim().replace(/^"+|"+$/g, '');
+    header += `; report-to=${endpointToken}`;
+  }
+  return header;
+}
+
+// Pre-computed Connection-Allowlist and Content-Security-Policy headers
+export const CONNECTION_ALLOWLIST_HEADER = buildConnectionAllowlistHeader({
+  allowSelf: true,
+  patterns: ['https://images.unsplash.com'],
+});
+
+export const CSP_HEADER = [
+  "default-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "connect-src 'self' https://images.unsplash.com",
+  "script-src 'self' 'unsafe-inline'",
+  "style-src 'self' 'unsafe-inline'",
+  "form-action 'self'",
+  "frame-ancestors 'none'",
+  "object-src 'none'",
+  "base-uri 'self'",
+].join('; ');
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.mjs': 'application/javascript; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.gif': 'image/gif',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon',
+  '.txt': 'text/plain; charset=utf-8',
+};
+
+// In-memory subscriber list
+export const subscribers = [];
+
+export function isValidEmail(email) {
+  if (typeof email !== 'string') return false;
+  const trimmed = email.trim();
+  return /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/.test(
+    trimmed
+  );
+}
+
+/**
+ * Applies security headers to the response object.
+ */
+export function applySecurityHeaders(res, req = null) {
+  res.setHeader('Vary', 'Sec-Fetch-Dest');
+  res.setHeader('Connection-Allowlist', CONNECTION_ALLOWLIST_HEADER);
+  res.setHeader('Content-Security-Policy', CSP_HEADER);
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('X-Frame-Options', 'SAMEORIGIN');
+}
+
+/**
+ * Handles incoming HTTP requests.
+ */
+export function requestHandler(req, res) {
+  applySecurityHeaders(res, req);
+
+  const parsedUrl = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
+  const pathname = parsedUrl.pathname;
+
+  // Handle preflight OPTIONS
+  if (req.method === 'OPTIONS') {
+    res.writeHead(204, {
+      'Allow': 'GET, POST, OPTIONS',
+    });
+    res.end();
+    return;
+  }
+
+  // Newsletter signup endpoints
+  if (pathname === '/api/newsletter' || pathname === '/newsletter' || pathname === '/subscribe' || pathname === '/api/subscribe') {
+    if (req.method === 'POST') {
+      let body = '';
+      req.on('data', (chunk) => {
+        body += chunk;
+        if (body.length > 1e6) {
+          req.destroy();
+        }
+      });
+
+      req.on('end', () => {
+        let email = '';
+        const contentType = req.headers['content-type'] || '';
+
+        if (contentType.includes('application/json')) {
+          try {
+            const parsed = JSON.parse(body);
+            email = parsed.email;
+          } catch (_) {
+            res.writeHead(400, { 'Content-Type': 'application/json' });
+            res.end(JSON.stringify({ success: false, error: 'Invalid JSON payload' }));
+            return;
+          }
+        } else if (contentType.includes('application/x-www-form-urlencoded')) {
+          const params = new URLSearchParams(body);
+          email = params.get('email');
+        } else {
+          try {
+            const parsed = JSON.parse(body);
+            email = parsed.email;
+          } catch (_) {
+            const params = new URLSearchParams(body);
+            email = params.get('email');
+          }
+        }
+
+        if (!email || !isValidEmail(email)) {
+          res.writeHead(400, { 'Content-Type': 'application/json' });
+          res.end(
+            JSON.stringify({
+              success: false,
+              error: 'Invalid email address',
+              message: 'Please provide a valid email address.',
+            })
+          );
+          return;
+        }
+
+        const trimmedEmail = email.trim().toLowerCase();
+        subscribers.push({
+          email: trimmedEmail,
+          subscribedAt: new Date().toISOString(),
+        });
+
+        // Non-AJAX form submissions can redirect back to homepage
+        const acceptHeader = req.headers['accept'] || '';
+        if (contentType.includes('application/x-www-form-urlencoded') && !acceptHeader.includes('application/json')) {
+          res.writeHead(303, { Location: '/?subscribed=true' });
+          res.end();
+          return;
+        }
+
+        res.writeHead(200, { 'Content-Type': 'application/json' });
+        res.end(
+          JSON.stringify({
+            success: true,
+            message: 'Thank you for subscribing to The Daily Grind!',
+            email: trimmedEmail,
+          })
+        );
+      });
+      return;
+    }
+
+    if (req.method === 'GET') {
+      res.writeHead(200, { 'Content-Type': 'application/json' });
+      res.end(
+        JSON.stringify({
+          subscribers: subscribers.map((s) => s.email),
+          count: subscribers.length,
+        })
+      );
+      return;
+    }
+
+    res.writeHead(405, { 'Content-Type': 'application/json' });
+    res.end(JSON.stringify({ error: 'Method Not Allowed' }));
+    return;
+  }
+
+  // Health check endpoint
+  if (pathname === '/health' || pathname === '/ping') {
+    res.writeHead(200, { 'Content-Type': 'application/json' });
+    res.end(JSON.stringify({ status: 'ok' }));
+    return;
+  }
+
+  // Static file serving
+  if (req.method !== 'GET' && req.method !== 'HEAD') {
+    res.writeHead(405, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Method Not Allowed');
+    return;
+  }
