+          if (selectField) {
+            const selectedOpt = selectField.options[selectField.selectedIndex];
+            const delta = parseFloat(selectedOpt.dataset.delta || '0');
+            addedDelta += delta;
+            const tag = document.createElement('span');
+            tag.className = 'spec-tag tag-option';
+            tag.textContent = selectField.value;
+            tagsContainer.appendChild(tag);
+          }
+
+          // 3. Addon checkboxes
+          const addons = card.querySelectorAll('.addon-checkbox:checked');
+          addons.forEach((addon) => {
+            const delta = parseFloat(addon.dataset.delta || '0');
+            addedDelta += delta;
+            const tag = document.createElement('span');
+            tag.className = 'spec-tag tag-addon';
+            tag.textContent = `+ ${addon.value}`;
+            tagsContainer.appendChild(tag);
+          });
+
+          // Calculate final price
+          const finalPrice = Math.max(0, basePrice + addedDelta).toFixed(2);
+          priceEl.textContent = `$${finalPrice}`;
+        });
+      }
+
+      /**
+       * Toggles the card customization panel with a scoped transition
+       */
+      function toggleCustomizationPanel(card) {
+        const toggleBtn = card.querySelector('.customize-toggle-btn');
+        const panel = card.querySelector('.customization-panel');
+        if (!toggleBtn || !panel) return;
+
+        const isOpening = panel.hidden;
+
+        // Scoped transition on card
+        runScopedTransition(card, () => {
+          panel.hidden = !isOpening;
+          toggleBtn.setAttribute('aria-expanded', String(isOpening));
+        });
+      }
+
+      /**
+       * Attaches event listeners to interactive elements inside a card
+       */
+      function attachCardListeners(card) {
+        // Move Left
+        card.querySelector('.btn-move-left')?.addEventListener('click', () => {
+          moveCardLeft(card);
+        });
+
+        // Move Right
+        card.querySelector('.btn-move-right')?.addEventListener('click', () => {
+          moveCardRight(card);
+        });
+
+        // Remove
+        card.querySelector('.btn-remove')?.addEventListener('click', () => {
+          removeCard(card);
+        });
+
+        // Toggle customization panel
+        card.querySelector('.customize-toggle-btn')?.addEventListener('click', () => {
+          toggleCustomizationPanel(card);
+        });
+
+        // Customization inputs (radio, select, checkbox)
+        card.querySelectorAll('input[type="radio"]').forEach((radio) => {
+          radio.addEventListener('change', () => updateCardCustomizations(card));
+        });
+
+        card.querySelectorAll('.field-select').forEach((select) => {
+          select.addEventListener('change', () => updateCardCustomizations(card));
+        });
+
+        card.querySelectorAll('.addon-checkbox').forEach((checkbox) => {
+          checkbox.addEventListener('change', () => updateCardCustomizations(card));
+        });
+      }
+
+      // Global buttons
+      shuffleBtn?.addEventListener('click', shuffleCards);
+      restoreBtn?.addEventListener('click', restoreCards);
+      emptyRestoreBtn?.addEventListener('click', restoreCards);
+
+      // Initialize all cards present in the DOM
+      grid.querySelectorAll('.card').forEach((card) => {
+        attachCardListeners(card);
+      });
+
+      // Initial control states
+      updateCardControls();
+    })();
+  </script>
 </body>

 </html>

