+    document.addEventListener('DOMContentLoaded', () => {
+      // Select all navigation links and elements with data-scroll-target
+      const scrollLinks = document.querySelectorAll('nav a, [data-scroll-target]');
+
+      function getTargetElement(link) {
+        const targetAttr = link.getAttribute('data-scroll-target') || link.getAttribute('href');
+        if (!targetAttr) return null;
+        const targetId = targetAttr.startsWith('#') ? targetAttr.substring(1) : targetAttr;
+        return document.getElementById(targetId);
+      }
+
+      function smoothScrollTo(target, callback) {
+        const nav = document.querySelector('nav');
+        const navHeight = nav ? nav.offsetHeight : 0;
+        const targetRect = target.getBoundingClientRect();
+        const targetTop = Math.max(0, Math.round(targetRect.top + window.pageYOffset - navHeight - 15));
+        const startPosition = window.pageYOffset;
+        const distance = Math.abs(targetTop - startPosition);
+
+        // Check for reduced motion preference
+        const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
+        if (distance < 3 || prefersReducedMotion) {
+          window.scrollTo({
+            top: targetTop,
+            behavior: prefersReducedMotion ? 'auto' : 'smooth'
+          });
+          callback();
+          return;
+        }
+
+        let isFinished = false;
+        const finish = () => {
+          if (isFinished) return;
+          isFinished = true;
+          cleanup();
+          callback();
+        };
+
+        let scrollTimeout = null;
+        const onScroll = () => {
+          clearTimeout(scrollTimeout);
+          // When scrolling has stopped for 100ms, smooth scroll has completed
+          scrollTimeout = setTimeout(finish, 100);
+        };
+
+        const onScrollEnd = () => {
+          finish();
+        };
+
+        const cleanup = () => {
+          clearTimeout(scrollTimeout);
+          clearTimeout(safetyTimeout);
+          window.removeEventListener('scrollend', onScrollEnd);
+          window.removeEventListener('scroll', onScroll);
+        };
+
+        // Listen for modern browser scrollend event
+        if ('onscrollend' in window) {
+          window.addEventListener('scrollend', onScrollEnd, { once: true });
+        }
+        window.addEventListener('scroll', onScroll, { passive: true });
+
+        // Trigger native smooth scrolling to the calculated position
+        window.scrollTo({
+          top: targetTop,
+          behavior: 'smooth'
+        });
+
+        // Fallback safety timeout in case scrollend or scroll event doesn't fire
+        const safetyDuration = Math.min(Math.max(distance * 0.8, 400), 1500);
+        const safetyTimeout = setTimeout(finish, safetyDuration + 150);
+      }
+
+      scrollLinks.forEach(link => {
+        link.addEventListener('click', (e) => {
+          const target = getTargetElement(link);
+          if (!target) return;
+
+          e.preventDefault();
+
+          // Update active styling on navigation items
+          document.querySelectorAll('nav a').forEach(a => a.classList.remove('active'));
