+    if (supportsScrollTargetGroup) {
+      const syncAriaCurrent = () => {
+        const currentLink = document.querySelector('nav ul a:target-current');
+        navLinks.forEach(link => {
+          link.setAttribute('aria-current', link === currentLink ? 'true' : 'false');
+        });
+      };
+
+      // Initial check on load
+      syncAriaCurrent();
+
+      // Update aria-current on scrollend
+      document.addEventListener('scrollend', syncAriaCurrent);
+
+      // Throttled sync on scroll for real-time aria-current mirroring
+      let ticking = false;
+      window.addEventListener('scroll', () => {
+        if (!ticking) {
+          window.requestAnimationFrame(() => {
+            syncAriaCurrent();
+            ticking = false;
+          });
+          ticking = true;
+        }
+      }, { passive: true });
+    } else {
+      // Fallback for browsers not supporting scroll-target-group / :target-current
+      const updateActiveLink = (activeId) => {
+        navLinks.forEach(link => {
+          const isActive = Boolean(activeId && link.getAttribute('href') === `#${activeId}`);
+          link.classList.toggle('target-current', isActive);
+          link.setAttribute('aria-current', isActive ? 'true' : 'false');
+        });
+      };
+
+      const observer = new IntersectionObserver((entries) => {
+        entries.forEach(entry => {
+          if (entry.isIntersecting) {
+            const id = entry.target.getAttribute('id');
+            updateActiveLink(id);
+          }
+        });
+      }, { rootMargin: '-50% 0px -50% 0px', threshold: 0 });
