+      if (typeof this.options.onFocusChange === 'function') {
+        this.options.onFocusChange(targetCard, prevActive);
+      }
+    }
+
+    findNextCard(currentCard, direction) {
+      const cards = this.getCards();
+      if (cards.length === 0) return null;
+      if (!currentCard) return cards[0];
+
+      const rows = this.getVisualRows();
+      if (rows.length === 0) return cards[0];
+
+      let curRowIdx = -1;
+      let curColIdx = -1;
+
+      for (let r = 0; r < rows.length; r++) {
+        for (let c = 0; c < rows[r].length; c++) {
+          if (rows[r][c].card === currentCard) {
+            curRowIdx = r;
+            curColIdx = c;
+            break;
+          }
+        }
+        if (curRowIdx !== -1) break;
+      }
+
+      if (curRowIdx === -1) return cards[0];
+
+      const currentRow = rows[curRowIdx];
+      const isSingleCol = rows.every(r => r.length === 1);
+
+      switch (direction) {
+        case 'right':
+          if (isSingleCol) {
+            // In 1D list, right moves to next card
+            if (curRowIdx < rows.length - 1) return rows[curRowIdx + 1][0].card;
+            return rows[0][0].card;
+          }
+          if (curColIdx < currentRow.length - 1) {
+            return currentRow[curColIdx + 1].card;
+          } else if (curRowIdx < rows.length - 1) {
+            return rows[curRowIdx + 1][0].card;
+          } else {
+            return rows[0][0].card;
+          }
+
+        case 'left':
+          if (isSingleCol) {
+            // In 1D list, left moves to previous card
+            if (curRowIdx > 0) return rows[curRowIdx - 1][0].card;
+            return rows[rows.length - 1][0].card;
+          }
+          if (curColIdx > 0) {
+            return currentRow[curColIdx - 1].card;
+          } else if (curRowIdx > 0) {
+            const prevRow = rows[curRowIdx - 1];
+            return prevRow[prevRow.length - 1].card;
+          } else {
+            const lastRow = rows[rows.length - 1];
+            return lastRow[lastRow.length - 1].card;
+          }
+
+        case 'down':
+          if (curRowIdx < rows.length - 1) {
+            const nextRow = rows[curRowIdx + 1];
+            const curX = currentRow[curColIdx].centerX;
+            let closest = nextRow[0];
+            let minDist = Math.abs(closest.centerX - curX);
+            for (let i = 1; i < nextRow.length; i++) {
+              const dist = Math.abs(nextRow[i].centerX - curX);
+              if (dist < minDist) {
+                minDist = dist;
+                closest = nextRow[i];
+              }
+            }
+            return closest.card;
+          }
+          return currentCard;
+
+        case 'up':
+          if (curRowIdx > 0) {
+            const prevRow = rows[curRowIdx - 1];
+            const curX = currentRow[curColIdx].centerX;
+            let closest = prevRow[0];
+            let minDist = Math.abs(closest.centerX - curX);
+            for (let i = 1; i < prevRow.length; i++) {
+              const dist = Math.abs(prevRow[i].centerX - curX);
+              if (dist < minDist) {
+                minDist = dist;
+                closest = prevRow[i];
+              }
+            }
+            return closest.card;
+          }
+          return currentCard;
+
+        case 'home':
+          return currentRow[0].card;
+
+        case 'end':
+          return currentRow[currentRow.length - 1].card;
+
+        case 'first':
+          return rows[0][0].card;
+
+        case 'last': {
+          const lastRow = rows[rows.length - 1];
+          return lastRow[lastRow.length - 1].card;
+        }
+
+        case 'pagedown': {
+          const targetRowIdx = Math.min(rows.length - 1, curRowIdx + 2);
+          const targetRow = rows[targetRowIdx];
+          const curX = currentRow[curColIdx].centerX;
+          let closest = targetRow[0];
+          let minDist = Math.abs(closest.centerX - curX);
+          for (let i = 1; i < targetRow.length; i++) {
+            const dist = Math.abs(targetRow[i].centerX - curX);
+            if (dist < minDist) {
+              minDist = dist;
+              closest = targetRow[i];
+            }
+          }
+          return closest.card;
+        }
+
+        case 'pageup': {
+          const targetRowIdx = Math.max(0, curRowIdx - 2);
+          const targetRow = rows[targetRowIdx];
+          const curX = currentRow[curColIdx].centerX;
+          let closest = targetRow[0];
+          let minDist = Math.abs(closest.centerX - curX);
+          for (let i = 1; i < targetRow.length; i++) {
+            const dist = Math.abs(targetRow[i].centerX - curX);
+            if (dist < minDist) {
+              minDist = dist;
+              closest = targetRow[i];
+            }
+          }
+          return closest.card;
+        }
