+      if (typeof this.options.onLayoutChange === 'function') {
+        this.options.onLayoutChange(layoutMode);
+      }
+    }
+
+    _announceLayoutChange(layoutMode) {
+      const announcer = document.getElementById(this.options.liveRegionId);
+      if (!announcer) return;
+
+      const cardsCount = this.getCards().length;
+      const modeNames = {
+        grid: 'Grid view (3 columns)',
+        list: 'List view (single column)',
+        compact: 'Compact view (4 columns)'
+      };
+
+      const friendlyName = modeNames[layoutMode] || layoutMode;
+      announcer.textContent = `Switched to ${friendlyName}. ${cardsCount} items available.`;
+    }
+
+    _setupToolbar() {
+      if (typeof document === 'undefined') return;
+
+      const toolbar = document.querySelector(this.options.toolbarSelector);
+      if (!toolbar) return;
+
+      const buttons = toolbar.querySelectorAll(this.options.layoutBtnSelector);
+      buttons.forEach(btn => {
+        btn.addEventListener('click', (e) => {
+          e.preventDefault();
+          const targetLayout = btn.dataset.layout;
+          if (targetLayout) {
+            this.setLayout(targetLayout, true);
+          }
+        });
