+            const curIdx = btnList.indexOf(btn);
+            const nextIdx = (curIdx + 1) % btnList.length;
+            btnList[nextIdx].focus();
+            const targetLayout = btnList[nextIdx].dataset.layout;
+            if (targetLayout) this.setLayout(targetLayout, true);
+          } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
+            e.preventDefault();
