+            const curIdx = btnList.indexOf(btn);
+            const prevIdx = (curIdx - 1 + btnList.length) % btnList.length;
+            btnList[prevIdx].focus();
+            const targetLayout = btnList[prevIdx].dataset.layout;
+            if (targetLayout) this.setLayout(targetLayout, true);
+          }
+        });
+      });
