+      this._updateToolbarButtons(this.currentLayout);
+    }
+
+    _updateToolbarButtons(layoutMode) {
+      if (typeof document === 'undefined') return;
+
+      const toolbar = document.querySelector(this.options.toolbarSelector);
+      if (!toolbar) return;
+
+      const buttons = toolbar.querySelectorAll(this.options.layoutBtnSelector);
