+      const isCardFocused = target === card;
+      const isBtnFocused = target.classList && target.classList.contains('btn');
+
+      switch (event.key) {
+        case 'ArrowRight':
+          event.preventDefault();
+          this.navigate('right');
+          break;
+
+        case 'ArrowLeft':
+          event.preventDefault();
+          this.navigate('left');
+          break;
+
+        case 'ArrowDown':
+          event.preventDefault();
+          this.navigate('down');
+          break;
+
+        case 'ArrowUp':
+          event.preventDefault();
+          this.navigate('up');
+          break;
+
+        case 'Home':
+          event.preventDefault();
+          this.navigate(event.ctrlKey || event.metaKey ? 'first' : 'home');
+          break;
+
+        case 'End':
+          event.preventDefault();
+          this.navigate(event.ctrlKey || event.metaKey ? 'last' : 'end');
+          break;
+
+        case 'PageDown':
+          event.preventDefault();
+          this.navigate('pagedown');
+          break;
+
+        case 'PageUp':
+          event.preventDefault();
+          this.navigate('pageup');
+          break;
+
+        case 'Enter':
+          if (isCardFocused) {
+            // Activate the card's primary action button
+            const btn = card.querySelector(this.options.actionSelector);
+            if (btn) {
+              btn.click();
+            }
+          }
+          break;
+
+        case ' ': // Spacebar
+          if (isCardFocused) {
+            event.preventDefault();
+            const btn = card.querySelector(this.options.actionSelector);
+            if (btn) {
+              btn.click();
+            }
+          }
+          break;
+
+        case 'Escape':
+          if (isBtnFocused) {
+            event.preventDefault();
+            this.focusCard(card);
+          }
+          break;
+
+        case 'Tab':
