+          // If on card without shift: tab moves to internal action button
+          // If on button without shift: natural tab order exits grid to next element
+          // If on button with shift: tab moves back to card
+          // If on card with shift: natural tab order exits grid backwards
+          break;
+      }
+    }
+
+    _onFocusIn(event) {
