+      if (card && card !== this.activeCard) {
+        this.focusCard(card, { preventFocus: true });
+      }
+    }
+
+    _onClick(event) {
+      const card = event.target.closest(this.options.itemSelector);
+      if (card) {
+        this.focusCard(card);
+      }
+    }
+
+    _onResize() {
+      this.syncAria();
+    }
+
+    destroy() {
+      this.container.removeEventListener('keydown', this._boundKeyDown);
