+        <p>Bold, smokey, and perfect for a morning boost.</p>
+        <a href="/menu/espresso" class="btn">View Details</a>
+      </div>`,
+      `<div class="card">
+        <h3>Cold Brew</h3>
+        <p>Steeped for 18 hours for maximum smoothness.</p>
+        <a href="/menu/cold-brew" class="btn">View Details</a>
+      </div>`
+    ];
+
+    // Function to dynamically render Seasonal Favorites cards from HTML strings
+    function renderSeasonalFavorites(cards = seasonalFavoritesHTML) {
+      const container = document.getElementById('seasonal-favorites') || document.querySelector('section .grid') || document.querySelector('.grid');
+      if (!container) return;
+
+      const rawHTML = Array.isArray(cards) ? cards.join('\n') : String(cards);
+
+      let safeHTML;
+      if (window.DOMPurify && typeof window.DOMPurify.sanitize === 'function') {
+        safeHTML = window.DOMPurify.sanitize(rawHTML, { RETURN_TRUSTED_TYPE: true });
+      } else if (window.trustedTypes && window.trustedTypes.defaultPolicy) {
+        safeHTML = window.trustedTypes.defaultPolicy.createHTML(rawHTML);
+      } else {
+        safeHTML = fallbackSanitize(rawHTML);
+      }
+
+      container.innerHTML = safeHTML;
+    }
+
+    // Expose helpers and data globally
+    window.seasonalFavoritesHTML = seasonalFavoritesHTML;
+    window.seasonalFavorites = seasonalFavoritesHTML;
+    window.renderSeasonalFavorites = renderSeasonalFavorites;
+
+    // Initial render
+    if (document.readyState === 'loading') {
+      document.addEventListener('DOMContentLoaded', function () {
+        renderSeasonalFavorites();
+      });
+    } else {
+      renderSeasonalFavorites();
+    }
+  </script>
+
