+        const acceptsHtml = (req.headers.accept || '').includes('text/html') &&
+          !(req.headers['content-type'] || '').includes('application/json');
+
+        if (acceptsHtml) {
+          res.writeHead(200, { 'Content-Type': 'text/html; charset=UTF-8' });
+          res.end(`<!DOCTYPE html>
+<html lang="en">
