+  <meta charset="UTF-8">
+  <title>Welcome to Daily Grind Rewards</title>
+  <style>
+    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background: #fafafa; color: #3e2723; display: flex; justify-content: center; align-items: center; min-height: 100vh; margin: 0; }
+    .card { background: white; padding: 40px; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.1); max-width: 500px; text-align: center; }
+    h1 { color: #4e342e; margin-bottom: 15px; }
+    .badge { background: #4caf50; color: white; padding: 6px 14px; border-radius: 20px; font-weight: bold; display: inline-block; margin-bottom: 20px; }
+    .btn { display: inline-block; background: #4e342e; color: white; padding: 12px 25px; text-decoration: none; border-radius: 6px; margin-top: 25px; font-weight: bold; }
+  </style>
+</head>
+<body>
+  <div class="card">
+    <div class="badge">✓ Email Verified by Browser</div>
+    <h1>Welcome, ${name}!</h1>
+    <p>Your rewards account for <strong>${verifiedEmail}</strong> is active.</p>
+    <p>Your email was confirmed directly by your browser without sending a one-time passcode or magic link!</p>
+    <p><strong>50 Welcome Stars</strong> have been added to your balance.</p>
+    <a href="/" class="btn">Return to The Daily Grind</a>
+  </div>
+</body>
+</html>`);
+          return;
+        }
+
+        res.writeHead(200, { 'Content-Type': 'application/json' });
+        res.end(JSON.stringify({
+          success: true,
+          verified: true,
+          email: verifiedEmail,
+          name,
+          stars: 50,
