+          verified: false,
+          error: 'Internal server error during verification: ' + err.message
+        }));
+        return;
+      }
+    }
+  }
+
+  // GET /api/rewards/members - list registered members
+  if (method === 'GET' && pathname === '/api/rewards/members') {
+    res.writeHead(200, { 'Content-Type': 'application/json' });
