+        composed: true,
+        detail: this.coffeeData
+      })
+    );
+  };
+
+  #onOrderClick = (e) => {
+    e.stopPropagation();
+    this.dispatchEvent(
+      new CustomEvent('coffee-order', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          ...this.coffeeData,
