+            id="tab-cold"
+          >
+            Cold Brews
+          </button>
+          <button
+            type="button"
+            class="filter-btn"
+            part="filter-btn"
+            role="tab"
+            aria-selected="false"
+            tabindex="-1"
+            data-category="espresso"
+            id="tab-espresso"
+          >
+            Espresso
+          </button>
+        </div>
+      </div>
+    </div>
