+/**
+ * DailyNav - Accessible, responsive Web Component for the site navigation bar.
+ * Encapsulates mobile hamburger toggle, keyboard navigation, and live order counter.
+ */
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <style>
