+
+    .nav-links li a:hover {
+      color: var(--_accent);
+    }
+
+    .nav-links li a:focus-visible {
+      outline: 2px solid var(--_accent);
+      outline-offset: 2px;
+    }
+
+    .logout-link {
+      border: 1px solid var(--_accent) !important;
+      padding: 5px 14px !important;
+      border-radius: 4px;
+      color: var(--_accent) !important;
+      transition: background 0.2s ease, color 0.2s ease !important;
+    }
+
+    .logout-link:hover {
+      background: var(--_accent) !important;
+      color: var(--_primary) !important;
+    }
+
+    /* Cart / Order Indicator Button */
+    .cart-btn {
+      background: rgba(255, 255, 255, 0.15);
+      border: 1px solid rgba(255, 255, 255, 0.25);
+      color: #ffffff;
+      border-radius: 999px;
+      padding: 6px 14px;
+      display: inline-flex;
+      align-items: center;
+      gap: 0.45rem;
+      font: inherit;
+      font-size: 0.88rem;
+      font-weight: 600;
+      cursor: pointer;
+      transition: all 0.2s ease;
+    }
+
+    .cart-btn:hover {
+      background: rgba(255, 255, 255, 0.25);
+      border-color: var(--_accent);
+      color: var(--_accent);
+    }
+
+    .cart-btn:focus-visible {
+      outline: 2px solid var(--_accent);
+      outline-offset: 2px;
+    }
+
+    .cart-badge {
+      background: var(--_accent);
+      color: var(--_primary);
+      font-size: 0.75rem;
+      font-weight: 800;
+      min-width: 20px;
+      height: 20px;
+      padding: 0 5px;
+      border-radius: 10px;
+      display: inline-flex;
+      align-items: center;
+      justify-content: center;
+      transition: transform 0.2s ease;
+    }
+
+    .bump {
+      animation: bump-anim 0.3s ease-out;
+    }
+
+    @keyframes bump-anim {
+      0% { transform: scale(1); }
+      50% { transform: scale(1.35); }
+      100% { transform: scale(1); }
+    }
+
+    /* Mobile Hamburger Toggle */
+    .nav-toggle {
+      display: none;
+      background: transparent;
+      border: none;
+      color: #ffffff;
+      padding: 8px;
+      cursor: pointer;
+      font: inherit;
+      border-radius: 4px;
+    }
+
+    .nav-toggle:focus-visible {
+      outline: 2px solid var(--_accent);
+      outline-offset: 2px;
