+
+    .nav-toggle svg {
+      width: 26px;
+      height: 26px;
+      fill: none;
+      stroke: currentColor;
+      stroke-width: 2;
+    }
+
+    /* Responsive Mobile Navigation */
+    @media (max-width: 820px) {
+      .nav-toggle {
+        display: block;
+      }
+
+      .nav-links {
+        display: none;
+        position: absolute;
+        top: 100%;
+        left: 0;
+        right: 0;
+        background: var(--_primary);
+        flex-direction: column;
+        padding: 1.5rem 2rem;
