+        box-shadow: 0 6px 14px rgba(0, 0, 0, 0.25);
+        border-top: 1px solid rgba(255, 255, 255, 0.1);
+      }
+
+      .nav-links[data-open="true"] {
+        display: flex;
+      }
+
+      .nav-links li {
+        width: 100%;
+      }
+
+      .nav-links li a {
+        display: block;
+        padding: 0.5rem 0;
+        font-size: 1.05rem;
+      }
+
+      .logout-link {
+        display: inline-block !important;
+        margin-top: 0.5rem;
+      }
+    }
+  </style>
+
+  <nav part="nav" aria-label="Main Navigation">
+    <a href="/" class="brand" part="brand">
+      <svg class="logo-icon" viewBox="0 0 24 24" aria-hidden="true">
+        <path d="M20 3H4v10c0 2.21 1.79 4 4 4h6c2.21 0 4-1.79 4-4v-3h2c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm0 5h-2V5h2v3zM4 19h16v2H4z"/>
+      </svg>
+      <span class="logo-text" part="logo">
+        <slot name="logo">THE DAILY GRIND</slot>
+      </span>
+    </a>
+
+    <div class="nav-actions">
+      <button
+        type="button"
+        class="cart-btn"
+        part="cart-btn"
+        id="cart-btn"
+        aria-label="Order summary: 0 items"
+      >
+        <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
+          <path d="M7 18c-1.1 0-1.99.9-1.99 2S5.9 22 7 22s2-.9 2-2-.9-2-2-2zM1 2v2h2l3.6 7.59-1.35 2.45c-.16.28-.25.61-.25.96 0 1.1.9 2 2 2h12v-2H7.42c-.14 0-.25-.11-.25-.25l.03-.12.9-1.63h7.45c.75 0 1.41-.41 1.75-1.03l3.58-6.49c.08-.14.12-.31.12-.48 0-.55-.45-1-1-1H5.21l-.94-2H1zm16 16c-1.1 0-1.99.9-1.99 2s.89 2 1.99 2 2-.9 2-2-.9-2-2-2z"/>
+        </svg>
+        <span>Order</span>
+        <span class="cart-badge" part="cart-badge" id="cart-count">0</span>
+      </button>
+
+      <button
+        type="button"
+        class="nav-toggle"
+        part="nav-toggle"
+        id="nav-toggle"
+        aria-expanded="false"
+        aria-controls="nav-links"
+        aria-label="Toggle navigation menu"
+      >
+        <svg viewBox="0 0 24 24" aria-hidden="true">
+          <path class="menu-icon" d="M3 12h18M3 6h18M3 18h18" stroke-linecap="round"/>
+        </svg>
+      </button>
+    </div>
+
+    <ul class="nav-links" part="nav-links" id="nav-links" data-open="false">
+      <slot name="links">
+        <li><a href="/menu">Menu</a></li>
+        <li><a href="/locations">Locations</a></li>
+        <li><a href="/rewards">Rewards</a></li>
+        <li><a href="/account">My Account</a></li>
+        <li><a href="/logout" class="logout-link">Logout</a></li>
+      </slot>
+    </ul>
+  </nav>
+`;
+
+export class DailyNav extends HTMLElement {
+  #toggleBtn;
+  #navLinks;
+  #cartBtn;
+  #cartCountEl;
+  #orderCount = 0;
+  #orders = [];
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this.shadowRoot.append(template.content.cloneNode(true));
+
+    this.#toggleBtn = this.shadowRoot.getElementById('nav-toggle');
+    this.#navLinks = this.shadowRoot.getElementById('nav-links');
+    this.#cartBtn = this.shadowRoot.getElementById('cart-btn');
+    this.#cartCountEl = this.shadowRoot.getElementById('cart-count');
+  }
+
+  connectedCallback() {
+    this.#toggleBtn.addEventListener('click', this.#onToggleMenu);
+    this.#cartBtn.addEventListener('click', this.#onCartClick);
+    document.addEventListener('keydown', this.#onDocumentKeyDown);
+    document.addEventListener('click', this.#onDocumentClick);
+
+    // Listen globally for coffee-order events from any coffee-card or modal
+    window.addEventListener('coffee-order', this.#onCoffeeOrder);
+  }
+
+  disconnectedCallback() {
+    this.#toggleBtn.removeEventListener('click', this.#onToggleMenu);
+    this.#cartBtn.removeEventListener('click', this.#onCartClick);
+    document.removeEventListener('keydown', this.#onDocumentKeyDown);
+    document.removeEventListener('click', this.#onDocumentClick);
+    window.removeEventListener('coffee-order', this.#onCoffeeOrder);
+  }
+
+  #onToggleMenu = (e) => {
+    e.stopPropagation();
+    const isOpen = this.#navLinks.getAttribute('data-open') === 'true';
+    this.setMenuOpen(!isOpen);
+  };
+
+  setMenuOpen(open) {
+    this.#navLinks.setAttribute('data-open', open ? 'true' : 'false');
+    this.#toggleBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
+  }
+
+  #onDocumentKeyDown = (e) => {
+    if (e.key === 'Escape' && this.#navLinks.getAttribute('data-open') === 'true') {
+      this.setMenuOpen(false);
+      this.#toggleBtn.focus();
+    }
+  };
+
+  #onDocumentClick = (e) => {
+    if (!this.contains(e.target) && this.#navLinks.getAttribute('data-open') === 'true') {
+      this.setMenuOpen(false);
+    }
+  };
+
+  #onCoffeeOrder = (e) => {
+    const item = e.detail;
+    const qty = Number(item?.quantity) || 1;
+    this.#orderCount += qty;
+    this.#orders.push(item);
+    this.#updateCartDisplay();
+  };
+
+  #updateCartDisplay() {
+    if (this.#cartCountEl) {
+      this.#cartCountEl.textContent = String(this.#orderCount);
+      this.#cartCountEl.classList.remove('bump');
+      // Trigger reflow for animation restart
+      void this.#cartCountEl.offsetWidth;
+      this.#cartCountEl.classList.add('bump');
+    }
+    if (this.#cartBtn) {
+      this.#cartBtn.setAttribute(
+        'aria-label',
+        `Order summary: ${this.#orderCount} ${this.#orderCount === 1 ? 'item' : 'items'}`
+      );
+    }
+  }
+
+  #onCartClick = () => {
+    this.dispatchEvent(
+      new CustomEvent('nav-cart-click', {
+        bubbles: true,
+        composed: true,
+        detail: { count: this.#orderCount, orders: this.#orders }
+      })
+    );
+  };
+}
+
+if (!customElements.get('daily-nav')) {
+  customElements.define('daily-nav', DailyNav);
+}
