+/**
+ * Accessible Coffee Customization & Quick View Modal Web Component
+ * <coffee-modal></coffee-modal>
+ */
+class CoffeeModal extends HTMLElement {
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this._isOpen = false;
+    this._triggerElement = null;
+    this._data = null;
+    this._basePrice = 4.5;
+    this._quantity = 1;
+    this._sizeExtra = 0.5; // Medium default
+    this._milkExtra = 0.0;
+  }
+
+  connectedCallback() {
+    this.render();
+    this._setupGlobalListeners();
+  }
+
+  disconnectedCallback() {
+    this._teardownGlobalListeners();
+  }
+
+  _setupGlobalListeners() {
+    this._handleKeyDown = this._handleKeyDown.bind(this);
+    this._handleExternalQuickView = (e) => {
+      this.open(e.detail, e.detail.triggerElement || e.target);
+    };
+
+    window.addEventListener('keydown', this._handleKeyDown);
+    window.addEventListener('coffee-quick-view', this._handleExternalQuickView);
+  }
+
+  _teardownGlobalListeners() {
+    window.removeEventListener('keydown', this._handleKeyDown);
+    window.removeEventListener('coffee-quick-view', this._handleExternalQuickView);
+  }
+
+  _handleKeyDown(e) {
+    if (!this._isOpen) return;
+
+    if (e.key === 'Escape') {
+      e.preventDefault();
+      this.close();
+      return;
+    }
+
+    if (e.key === 'Tab') {
+      this._trapFocus(e);
+    }
+  }
+
+  _trapFocus(e) {
+    const focusableElements = this.shadowRoot.querySelectorAll(
+      'button:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'
+    );
+    if (!focusableElements.length) return;
+
+    const firstElement = focusableElements[0];
+    const lastElement = focusableElements[focusableElements.length - 1];
+
+    if (e.shiftKey && document.activeElement === this && this.shadowRoot.activeElement === firstElement) {
+      e.preventDefault();
+      lastElement.focus();
+    } else if (!e.shiftKey && this.shadowRoot.activeElement === lastElement) {
+      e.preventDefault();
+      firstElement.focus();
+    }
+  }
+
+  open(data, triggerElement = null) {
+    this._data = data;
