+/**
+ * Accessible Hero Banner Web Component
+ * <hero-banner>
+ */
+class HeroBanner extends HTMLElement {
+  static get observedAttributes() {
+    return ['heading', 'subheading', 'cta-text', 'cta-href', 'bg-image'];
+  }
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+  }
+
+  get heading() {
+    return this.getAttribute('heading') || 'Wake Up Your Senses';
+  }
+
+  get subheading() {
+    return (
+      this.getAttribute('subheading') ||
+      'Ethically sourced, locally roasted, delivered to your cup.'
+    );
+  }
+
+  get ctaText() {
+    return this.getAttribute('cta-text') || 'Order Now';
+  }
+
+  get ctaHref() {
+    return this.getAttribute('cta-href') || '#menu';
+  }
+
+  get bgImage() {
+    return (
+      this.getAttribute('bg-image') ||
+      'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80'
+    );
+  }
+
+  connectedCallback() {
+    this.render();
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (oldValue !== newValue && this.shadowRoot && this.shadowRoot.hasChildNodes()) {
+      this.render();
+    }
+  }
+
+  render() {
+    this.shadowRoot.innerHTML = `
+      <style>
+        :host {
+          display: block;
+          --primary-color: var(--primary, #4e342e);
+          --accent-color: var(--accent, #ffab40);
+          font-family: inherit;
+        }
+
+        .hero {
