+          font-size: clamp(1.6rem, 3.5vw, 2.2rem);
+          font-weight: 800;
+          margin: 0 0 12px 0;
+          color: #ffffff;
+        }
+
+        .desc {
+          font-size: 1.05rem;
+          color: var(--secondary-color);
+          max-width: 580px;
+          margin: 0 auto 28px auto;
+          line-height: 1.5;
+        }
+
+        .form {
+          display: flex;
+          justify-content: center;
+          gap: 12px;
+          max-width: 500px;
+          margin: 0 auto;
+          flex-wrap: wrap;
+        }
+
+        .input-group {
+          flex: 1;
+          min-width: 240px;
+          text-align: left;
+        }
+
+        .sr-only {
+          position: absolute;
+          width: 1px;
+          height: 1px;
+          padding: 0;
+          margin: -1px;
+          overflow: hidden;
+          clip: rect(0, 0, 0, 0);
+          border: 0;
+        }
+
+        .email-input {
+          width: 100%;
+          padding: 14px 18px;
+          border-radius: 8px;
+          border: 2px solid transparent;
+          font-size: 1rem;
+          font-family: inherit;
+          box-sizing: border-box;
+          background: #ffffff;
+          color: #3e2723;
+        }
+
+        .email-input:focus {
+          outline: none;
+          border-color: var(--accent-color);
+          box-shadow: 0 0 0 3px rgba(255, 171, 64, 0.35);
+        }
+
+        .email-input.has-error {
+          border-color: #ef5350;
+        }
+
+        .btn-submit {
+          background: var(--accent-color);
+          color: #2e1c14;
+          font-weight: 700;
+          font-size: 1rem;
+          padding: 14px 24px;
+          border: none;
+          border-radius: 8px;
+          cursor: pointer;
+          font-family: inherit;
+          transition: background-color 0.2s, transform 0.15s;
+        }
+
+        .btn-submit:hover:not(:disabled) {
+          background: #ffa000;
+          transform: translateY(-1px);
+        }
+
+        .btn-submit:focus-visible {
+          outline: 2px solid #ffffff;
+          outline-offset: 3px;
+        }
+
+        .btn-submit:disabled {
+          opacity: 0.7;
+          cursor: not-allowed;
